// ── The Complete 18-Byte Header Parser (Env, Weight, & Alive) ──

const gatewayId = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const TARGET_CLOUD_SID = 16777216; 

let incoming = "";
if (Buffer.isBuffer(msg.payload)) incoming = msg.payload.toString('hex');
else if (msg.payload && typeof msg.payload.hex === 'string') incoming = msg.payload.hex;
else if (typeof msg.payload === 'string') incoming = msg.payload;
else return null;

let buf = (context.get('buf') || '') + incoming.replace(/\s+/g, '');
const out = [];

// 1. GARBAGE COLLECTOR
if (buf.length > 8192) {
    buf = ""; 
    context.set('buf', buf);
    node.warn("Buffer overflow prevented. Flushed garbage data.");
    return null;
}

// 2. OMNI-SIGNATURE SCANNER
while (buf.length > 0) {
    // Look for all three known packet types
    let sensorIdx = buf.indexOf("013a"); // Type 0x01 (Env), Length 58
    let weightIdx = buf.indexOf("026a"); // Type 0x02 (Weight), Length 106
    let aliveIdx  = buf.indexOf("040c"); // Type 0x04 (Alive), Length 12

    let startIndex = -1;
    let packetType = 0;

    // Find whichever valid signature appears first in the current chunk
    const indices = [
        { type: 1, idx: sensorIdx },
        { type: 2, idx: weightIdx },
        { type: 4, idx: aliveIdx }
    ].filter(obj => obj.idx !== -1);

    if (indices.length > 0) {
        const earliest = indices.reduce((prev, curr) => prev.idx < curr.idx ? prev : curr);
        startIndex = earliest.idx;
        packetType = earliest.type;
    }

    if (startIndex === -1) {
        if (buf.length > 50) buf = buf.slice(-50);
        break; 
    }

    // 3. EXTRACT THE 18-BYTE PACKET MODE HEADER
    if (startIndex < 36) {
        buf = buf.slice(startIndex + 2); 
        continue;
    }

    const headerHex = buf.slice(startIndex - 36, startIndex); 

    // ── THE BIG-ENDIAN FIX ──
    const trueUidHex = headerHex.slice(10, 18);
    let dynamicUid = 0; 
    if (/^[0-9a-fA-F]{8}$/.test(trueUidHex)) {
        dynamicUid = Buffer.from(trueUidHex, 'hex').readUInt32BE(0); 
    } else {
        buf = buf.slice(startIndex + 2);
        continue;
    }

    // ── EXTRACT METADATA ──
    const trueRssiHex = headerHex.slice(18, 20);
    let rawRssi = parseInt(trueRssiHex, 16);
    let trueRssi = (rawRssi / 2) - 121; // Match the old Gateway's exact dBm formula

    const networkLvl = parseInt(headerHex.slice(20, 22), 16) || 1;
    const hops = parseInt(headerHex.slice(22, 24), 16) || 1;
    const latency = parseInt(headerHex.slice(24, 26), 16) || 2;

    // 4. EXTRACT THE PAYLOAD DATA (Little-Endian)
    let expectedPayloadChars = 0;
    if (packetType === 1) expectedPayloadChars = 58 * 2;
    else if (packetType === 2) expectedPayloadChars = 106 * 2;
    else if (packetType === 4) expectedPayloadChars = 12 * 2;

    if (buf.length < startIndex + expectedPayloadChars) {
        break; // Wait for the rest of the serial chunk
    }

    const frameHex = buf.slice(startIndex, startIndex + expectedPayloadChars);
    buf = buf.slice(startIndex + expectedPayloadChars); 

    const bytes = [];
    for (let i = 0; i < frameHex.length; i += 2) {
        bytes.push(parseInt(frameHex.slice(i, i + 2), 16));
    }
    const view = new DataView(new Uint8Array(bytes).buffer);

    let extractedData = {};
    let messageDetail = "unknown";

    if (packetType === 1) {
        messageDetail = "sensor_telemetry";

        // Mapped exactly to sensor_telegram_t from sensors.h
        extractedData = {
            AirTemperature:      view.getFloat32(6,  true),
            AirPressure:         view.getFloat32(10, true),
            HumidityTemperature: view.getFloat32(14, true),
            Humidity:            view.getFloat32(18, true),
            LightALS:            view.getUint32(22,  true), // Parsed as integer based on C-struct behavior
            GASCO2:              view.getFloat32(26, true),
            GASTemperature:      view.getFloat32(30, true),
            GASHumidity:         view.getFloat32(34, true),
            GASNH3:              view.getFloat32(38, true),
            GASCO:               view.getFloat32(42, true),
            GASNO2:              view.getFloat32(46, true),
            BoardTemperature:    view.getFloat32(50, true),
            PT100Temperature:    view.getFloat32(54, true)
        };
    } else if (packetType === 2) {
        messageDetail = "weight_telemetry";
        const samples = [];
        for (let i = 6; i + 1 < bytes.length; i += 2) {
            samples.push(view.getUint16(i, true)); // Payload stays LE
        }
        extractedData = {
            count: samples.length,
            mean_weight: samples.reduce((a, b) => a + b, 0) / samples.length
        };
    } else if (packetType === 4) {
        messageDetail = "device_startup";
        extractedData = {
            hardware_mac: frameHex.slice(4, 20), 
            firmware: view.getUint16(10, true) // Payload stays LE
        };
    }

    // 5. BUILD THE FAI CLOUD ENVELOPE
    out.push({
        topic: `gateway/${gatewayId}/tinymesh/out`,
        payload: {
            "_meta": { "received": new Date().toISOString() },
            "block": 0,
            "data": JSON.stringify(extractedData), 
            "detail": messageDetail,               
            "hops": hops,
            "latency": latency,
            "network_lvl": networkLvl,
            "packet_num": Math.floor(Math.random() * 65535),
            "rssi": trueRssi, 
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid,  
            "raw_hex": frameHex 
        }
    });
}

context.set('buf', buf);

if (out.length === 0) return null;
if (out.length === 1) return out[0];
return [out];

// ── FAI Gateway Parser (v3.1 - Raw Payload, Correct UID) ──

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
const TARGET_CLOUD_SID = 16777216;

let incoming = "";
if (Buffer.isBuffer(msg.payload))           incoming = msg.payload.toString('hex');
else if (msg.payload?.hex)                  incoming = msg.payload.hex;
else if (typeof msg.payload === 'string')   incoming = msg.payload;
else return null;

let buf = (context.get('buf') || '') + incoming.replace(/\s+/g, '');
const out = [];

if (buf.length > 8192) {
    context.set('buf', '');
    node.warn("Buffer overflow — flushed");
    return null;
}

while (buf.length > 0) {
    const sensorIdx = buf.indexOf("013a");
    const weightIdx = buf.indexOf("026a");
    const aliveIdx  = buf.indexOf("040c");

    const candidates = [
        { type: 1, idx: sensorIdx },
        { type: 2, idx: weightIdx },
        { type: 4, idx: aliveIdx }
    ].filter(c => c.idx !== -1);

    if (!candidates.length) {
        if (buf.length > 50) buf = buf.slice(-50);
        break;
    }

    const { type: packetType, idx: startIndex } =
        candidates.reduce((a, b) => a.idx < b.idx ? a : b);

    // Need 18-byte (36 hex char) header before the payload signature
    if (startIndex < 36) { buf = buf.slice(startIndex + 2); continue; }

    const headerHex = buf.slice(startIndex - 36, startIndex);

    // UID: bytes 5-8 of header, Big-Endian
    const trueUidHex = headerHex.slice(10, 18);
    if (!/^[0-9a-fA-F]{8}$/.test(trueUidHex)) {
        buf = buf.slice(startIndex + 2);
        continue;
    }
    const dynamicUid = Buffer.from(trueUidHex, 'hex').readUInt32BE(0);

    // RSSI: raw integer as the backend expects (same format tinymesh-edge sent)
    const rawRssi = parseInt(headerHex.slice(18, 20), 16);

    const networkLvl = parseInt(headerHex.slice(20, 22), 16) || 1;
    const hops       = parseInt(headerHex.slice(22, 24), 16) || 1;
    const latency    = parseInt(headerHex.slice(24, 26), 16) || 2;

    const payloadLen = packetType === 1 ? 58 : packetType === 2 ? 106 : 12;
    const needed = startIndex + payloadLen * 2;
    if (buf.length < needed) break;

    const frameHex = buf.slice(startIndex, needed);
    buf = buf.slice(needed);

    out.push({
        topic: `gateway/${gatewaySerial}/tinymesh/out`,
        payload: {
            "_meta": { "received": new Date().toISOString().split('.')[0] + '+00:00' },
            "block":       0,
            "data":        frameHex,   // Raw C-struct hex — backend decodes this itself
            "detail":      "serial",
            "hops":        hops,
            "latency":     latency,
            "network_lvl": networkLvl,
            "packet_num":  Math.floor(Math.random() * 65535),
            "rssi":        rawRssi,    // Raw integer, not dBm — matches tinymesh-edge format
            "sid":         TARGET_CLOUD_SID,
            "type":        "event",
            "uid":         dynamicUid
        }
    });
}

context.set('buf', buf);
if (!out.length) return null;
return out.length === 1 ? out[0] : out;

// ── FAI wMBus Extractor (MC100 Format Match) ──

const gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

if (!Buffer.isBuffer(msg.payload)) return null;

const hexData = msg.payload.toString('hex').toLowerCase();
const base64Raw = msg.payload.toString('base64');

if (hexData.length < 50) return null;

// ── PARSE HEADER FIELDS ──
const lField = parseInt(hexData.substring(0, 2), 16);
const cField = parseInt(hexData.substring(2, 4), 16);

// Manufacturer (bytes 2-3, little-endian → 15-bit decode)
const manHex = hexData.substring(6, 8) + hexData.substring(4, 6);
const manInt = parseInt(manHex, 16);
const manufacturer =
    String.fromCharCode(((manInt >> 10) & 0x001F) + 64) +
    String.fromCharCode(((manInt >> 5)  & 0x001F) + 64) +
    String.fromCharCode((manInt & 0x001F) + 64);

// Device ID (bytes 4-7, little-endian BCD reversal)
const idHex = hexData.substring(8, 16);
const serialNumber = idHex.substring(6, 8) +
    idHex.substring(4, 6) +
    idHex.substring(2, 4) +
    idHex.substring(0, 2);

// Version and device type bytes
const version = parseInt(hexData.substring(16, 18), 16);
const ciField  = parseInt(hexData.substring(20, 22), 16);

// Full ID as the MC100 sends it (manufacturer + serial)
const fullId = manufacturer + serialNumber;

// RSSI — RC1180 with RSSI mode off means we don't have it;
// send a reasonable placeholder or omit
const rssiDbm = -52; // placeholder; adjust if you enable RSSI on dongle

msg.topic = `gateway/${gatewaySerial}/wmbus/out`;
msg.payload = {
    "_meta": {
        "received": new Date().toISOString().split('.')[0] + '+00:00',
        "receiver_id": "0000000000000000",
        "rssi": rssiDbm
    },
    "data": {
        "AField":       idHex.toUpperCase() + hexData.substring(16, 28).toUpperCase(),
        "CField":       cField,
        "CIField":      ciField,
        "ID":           "18" + serialNumber,
        "LField":       lField,
        "MField":       manInt,
        "Manufacturer": manufacturer,
        "SerialNumber": serialNumber
    },
    "raw":  base64Raw,
    "type": "wmbus"
};

return msg;

let joined = msg.payload;

// Safely set default values so it never crashes
let voltage = 0;
let amps = 0;
let partNumber = "Unknown CG Meter";
let serial = "Unknown";

// Helper function: Node-RED Modbus sometimes puts the array inside '.data'
function getArray(payloadPart) {
    if (!payloadPart) return null;
    return payloadPart.data ? payloadPart.data : payloadPart;
}

let volArr = getArray(joined.voltage);
let ampArr = getArray(joined.amps);
let modArr = getArray(joined.model);
let serArr = getArray(joined.serial);

// 1. Parse Voltage (Address 0)
if (volArr && volArr.length >= 2) {
    let rawVolts = (volArr[1] << 16) | volArr[0];
    voltage = rawVolts / 10;
}

// 2. Parse Amps (Address 12)
if (ampArr && ampArr.length >= 2) {
    let rawAmps = (ampArr[1] << 16) | ampArr[0];
    amps = rawAmps / 1000;
}

// 3. Identify Device Type (Address 11)
if (modArr && modArr.length >= 1) {
    let modelCode = modArr[0];
    if (modelCode === 332) partNumber = "EM330-DIN AV5";
    else if (modelCode === 341) partNumber = "EM340-DIN AV2";
    else partNumber = "Model Code: " + modelCode;
}

// 4. Parse Serial Number (Address 20480)
if (serArr) {
    serial = "";
    serArr.forEach(reg => {
        serial += String.fromCharCode(reg & 0xFF); // Extract LSB to ASCII
    });
}

// Build the exact MC100 output payload
msg.payload = {
    "DateTime": new Date().toISOString(),
    "Amp": parseFloat(amps.toFixed(3)),
    "AmpHour": 0, 
    "Voltage": parseFloat(voltage.toFixed(1)),
    "State": "",
    "Partnumber": partNumber,
    "Serialnumber": serial.trim(), 
    "FirmwareRevision": "0.0-1",
    "Type": "modbus-meter",
    "Meta": null
};

// --- NEW CODE: Build the exact MQTT Topic ---
// Grab the Gateway Serial from the Docker environment variables
let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

// Format: gateway/A100000155081224/power/out
msg.topic = `gateway/${gatewaySerial}/power/out`;

return msg;

let joined = msg.payload;

// Safely set default values so it never crashes
let voltage = 0;
let amps = 0;
let partNumber = "TIP SINUS";
let serial = "Unknown";

// Helper function: Node-RED Modbus sometimes puts the array inside '.data'
function getArray(payloadPart) {
    if (!payloadPart) return null;
    return payloadPart.data ? payloadPart.data : payloadPart;
}

// Notice I removed the '#' from the Serial name here!
let volArr = getArray(joined.voltage);
let ampArr = getArray(joined.amps);
let serArr = getArray(joined.serial);

// 1. Parse Voltage (Address 34)
if (volArr && volArr.length >= 2) {
    let rawVolts = (volArr[0] * 65536) + volArr[1];
    voltage = rawVolts / 1000;
}

// 2. Parse Amps (Address 36)
if (ampArr && ampArr.length >= 2) {
    let rawAmps = (ampArr[0] * 65536) + ampArr[1];
    amps = rawAmps / 1000;
}

// 3. Parse Serial Number (Address 4)
if (serArr && serArr.length >= 2) {
    let highHex = serArr[0].toString(16).padStart(4, '0');
    let lowHex = serArr[1].toString(16).padStart(4, '0');
    let rawSerial = (highHex + lowHex).toUpperCase();

    // Convert to integer to strip leading zeros, then back to string
    serial = parseInt(rawSerial, 10).toString(); 
}
// Build the exact MC100 output payload
msg.payload = {
    "DateTime": new Date().toISOString(),
    "Amp": parseFloat(amps.toFixed(3)),
    "AmpHour": 0, 
    "Voltage": parseFloat(voltage.toFixed(1)),
    "State": "",
    "Partnumber": partNumber,
    "Serialnumber": serial.trim(), 
    "FirmwareRevision": "0.0-1",
    "Type": "modbus-meter",
    "Meta": null
};

// --- Build the exact MQTT Topic ---
let gatewaySerial = env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";
msg.topic = `gateway/${gatewaySerial}/power/out`;

return msg;

// ── FAI Gateway Parser v9.1 — Session-aware duplicate protection ─────────────
//
// Arduino input:
//   One 50-byte LoRaWAN packet every approximately 3 minutes.
//
//   Byte 0:       protocol version
//   Byte 1:       number of weight samples
//   Bytes 2-3:    batch number, UInt16 LE
//   Bytes 4-39:   18 × weight readings, UInt16 LE
//   Bytes 40-41:  temperature × 100, Int16 LE
//   Bytes 42-43:  CO2 ppm, UInt16 LE
//   Bytes 44-45:  light lux, UInt16 LE
//   Bytes 46-47:  humidity × 100, UInt16 LE
//   Bytes 48-49:  pressure × 10, UInt16 LE
//
// Weight behaviour:
//   - The 18 Arduino readings are genuine spot readings taken 10 seconds apart.
//   - Each valid reading becomes a separate backend Type 0x02 event.
//   - Each Type 0x02 event contains the one weight repeated across all 50
//     legacy array positions.
//   - The 18 backend event timestamps are reconstructed at 10-second intervals.
//   - 0xFFFF means invalid and that specific event is omitted.
//   - Genuine 0 g readings are retained.
//
// Backend output:
//   Type 0x01: environmental packet, 58 bytes, signature 013a.
//   Type 0x02: weight packet, 106 bytes, signature 026a.
//
// There is no longer a cross-message weight queue.

// ============================================================================
// Configuration
// ============================================================================

const gatewaySerial =
    env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

const TARGET_CLOUD_SID = 16777216;

const EXPECTED_PAYLOAD_LENGTH = 50;
const EXPECTED_VERSION = 1;

const MAX_WEIGHT_SAMPLES = 18;
const WEIGHT_INTERVAL_MS = 10000;

const INVALID_WEIGHT = 0xFFFF;

// Retain a small duplicate history for each device.
const RECENT_MESSAGE_HISTORY = 64;
const STATE_NAMESPACE = "faiParserV91";

// ============================================================================
// ChirpStack event type
// ============================================================================
//
// This function can safely receive:
//   application/+/device/+/event/+
//
// A join event clears the duplicate history for that DevEUI. Other non-uplink
// event types are ignored.

const topicParts =
    String(msg.topic || "")
        .split("/")
        .filter(Boolean);

const eventType =
    topicParts.length > 0
        ? topicParts[topicParts.length - 1]
        : "up";

if (eventType === "join") {
    const joinDevEui =
        msg.payload &&
            msg.payload.deviceInfo &&
            msg.payload.deviceInfo.devEui
            ? String(
                msg.payload.deviceInfo.devEui
            ).toUpperCase()
            : null;

    if (joinDevEui) {
        global.set(
            `${STATE_NAMESPACE}_state_${joinDevEui}`,
            undefined
        );

        node.warn(
            `LoRaWAN session reset after join — device=${joinDevEui}`
        );

        node.status({
            fill: "blue",
            shape: "ring",
            text: `new session ${joinDevEui.slice(-8)}`
        });
    }

    return null;
}

if (eventType !== "up") {
    return null;
}

// ============================================================================
// Validate incoming ChirpStack message
// ============================================================================

if (
    !msg.payload ||
    !msg.payload.deviceInfo ||
    !msg.payload.deviceInfo.devEui ||
    msg.payload.data === undefined ||
    msg.payload.data === null
) {
    node.warn(
        "Invalid ChirpStack message: required payload fields are missing"
    );

    return null;
}

// ============================================================================
// Device identity
// ============================================================================

const devEui =
    String(msg.payload.deviceInfo.devEui).toUpperCase();

const uidHex =
    devEui.slice(-8);

if (!/^[0-9A-F]{8}$/.test(uidHex)) {
    node.warn(`Invalid DevEUI: ${devEui}`);
    return null;
}

const dynamicUid =
    parseInt(uidHex, 16);

if (!Number.isFinite(dynamicUid)) {
    node.warn(
        `Unable to calculate UID from DevEUI: ${devEui}`
    );

    return null;
}

// ============================================================================
// Decode compact LoRaWAN payload
// ============================================================================

let buf;

try {
    if (Buffer.isBuffer(msg.payload.data)) {
        buf = msg.payload.data;
    } else {
        buf = Buffer.from(
            String(msg.payload.data),
            "base64"
        );
    }
} catch (error) {
    node.warn(
        `Unable to decode LoRa payload from ${devEui}: ` +
        error.message
    );

    return null;
}

if (buf.length !== EXPECTED_PAYLOAD_LENGTH) {
    node.warn(
        `Unexpected payload length from ${devEui}: ` +
        `${buf.length} bytes; expected ${EXPECTED_PAYLOAD_LENGTH}`
    );

    return null;
}

// ============================================================================
// Decode header
// ============================================================================

const protocolVersion =
    buf.readUInt8(0);

const sampleCount =
    buf.readUInt8(1);

const batchNumber =
    buf.readUInt16LE(2);

if (protocolVersion !== EXPECTED_VERSION) {
    node.warn(
        `Unsupported payload version from ${devEui}: ` +
        `${protocolVersion}; expected ${EXPECTED_VERSION}`
    );

    return null;
}

if (
    sampleCount === 0 ||
    sampleCount > MAX_WEIGHT_SAMPLES
) {
    node.warn(
        `Invalid weight sample count from ${devEui}: ` +
        sampleCount
    );

    return null;
}

if (sampleCount !== MAX_WEIGHT_SAMPLES) {
    node.warn(
        `Partial weight batch from ${devEui}: ` +
        `${sampleCount}/${MAX_WEIGHT_SAMPLES}`
    );
}

// ============================================================================
// Session-aware duplicate protection
// ============================================================================
//
// The Arduino batch counter and the LoRaWAN frame counter both restart after
// a new OTAA session. Therefore, neither value is globally unique by itself.
//
// Protection is applied at two levels:
//
//   1. ChirpStack deduplicationId suppresses the exact same MQTT event.
//   2. DevAddr + session sequence + Arduino batch + complete payload suppresses
//      a retransmission of the same application batch within one session.
//
// A new session is detected when:
//   - a ChirpStack join event clears the state; or
//   - DevAddr changes; or
//   - fCnt returns to 0/1 after previously advancing beyond 1.

const stateKey =
    `${STATE_NAMESPACE}_state_${devEui}`;

let deviceState =
    global.get(stateKey);

if (
    !deviceState ||
    typeof deviceState !== "object" ||
    Array.isArray(deviceState)
) {
    deviceState = {
        sessionSequence: 0,
        devAddr: null,
        maxFrameCounter: -1,
        recentEventIds: [],
        recentBatches: []
    };
}

if (!Array.isArray(deviceState.recentEventIds)) {
    deviceState.recentEventIds = [];
}

if (!Array.isArray(deviceState.recentBatches)) {
    deviceState.recentBatches = [];
}

const normaliseHex = value =>
    String(value || "")
        .replace(/^0x/i, "")
        .replace(/[^0-9a-f]/gi, "")
        .toUpperCase();

const devAddr =
    normaliseHex(msg.payload.devAddr);

const frameCounter =
    Number(msg.payload.fCnt);

const hasFrameCounter =
    Number.isInteger(frameCounter) &&
    frameCounter >= 0;

const devAddrChanged =
    devAddr.length > 0 &&
    deviceState.devAddr &&
    devAddr !== deviceState.devAddr;

const frameCounterRestarted =
    hasFrameCounter &&
    frameCounter <= 1 &&
    Number.isInteger(deviceState.maxFrameCounter) &&
    deviceState.maxFrameCounter > 1;

if (devAddrChanged || frameCounterRestarted) {
    deviceState.sessionSequence =
        Number(deviceState.sessionSequence || 0) + 1;

    deviceState.recentEventIds = [];
    deviceState.recentBatches = [];
    deviceState.maxFrameCounter = -1;

    node.warn(
        `New LoRaWAN session detected — ` +
        `device=${devEui}, ` +
        `devAddr=${devAddr || "unknown"}, ` +
        `fCnt=${hasFrameCounter ? frameCounter : "unknown"}`
    );
}

if (devAddr.length > 0) {
    deviceState.devAddr = devAddr;
}

const payloadHex =
    buf.toString("hex");

const deduplicationId =
    String(
        msg.payload.deduplicationId || ""
    ).trim();

const exactEventSignature =
    deduplicationId
        ? `dedup:${deduplicationId}`
        : (
            devAddr.length > 0 &&
                hasFrameCounter
                ? `frame:${devAddr}:${frameCounter}:${payloadHex}`
                : `payload:${batchNumber}:${payloadHex}`
        );

if (
    deviceState.recentEventIds.includes(
        exactEventSignature
    )
) {
    node.warn(
        `Ignoring duplicate ChirpStack event — ` +
        `device=${devEui}, batch=${batchNumber}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `duplicate event ${batchNumber}`
    });

    return null;
}

const sessionIdentity =
    `session:${Number(deviceState.sessionSequence || 0)}:` +
    `${deviceState.devAddr || "unknown"}`;

const applicationBatchSignature =
    `${sessionIdentity}:batch:${batchNumber}:${payloadHex}`;

if (
    deviceState.recentBatches.includes(
        applicationBatchSignature
    )
) {
    node.warn(
        `Ignoring retransmitted application batch — ` +
        `device=${devEui}, ` +
        `session=${deviceState.sessionSequence}, ` +
        `batch=${batchNumber}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `retransmitted batch ${batchNumber}`
    });

    return null;
}

deviceState.recentEventIds.push(
    exactEventSignature
);

deviceState.recentBatches.push(
    applicationBatchSignature
);

if (
    deviceState.recentEventIds.length >
    RECENT_MESSAGE_HISTORY
) {
    deviceState.recentEventIds =
