// ── FAI LoRaWAN Device Dispatcher v1.2 ─────────────────────────────────────
//
// Output 1: ShedSensor events, including up and join
// Output 2: B Meters Hydrodigit uplinks
// Output 3: Talkpool OY1310 uplinks
// Output 4: joins, unknown devices/events and diagnostics

const payload =
    msg.payload || {};

const deviceInfo =
    payload.deviceInfo || {};

const tags =
    deviceInfo.tags &&
        typeof deviceInfo.tags === "object"
        ? deviceInfo.tags
        : {};

const profileName =
    String(
        deviceInfo.deviceProfileName || ""
    );

const eventType =
    String(msg.topic || "")
        .split("/")
        .filter(Boolean)
        .pop() || "unknown";

const sensorType =
    String(
        tags.sensor_type ||
        tags.device_type ||
        ""
    ).toLowerCase();

const manufacturer =
    String(
        tags.manufacturer || ""
    ).toLowerCase();

const model =
    String(
        tags.model || ""
    ).toLowerCase();

let deviceType = "";

// ============================================================================
// Device classification
// ============================================================================

// ShedSensor
if (
    sensorType === "shed_sensor" ||
    profileName === "RAK3272 Node"
) {
    deviceType = "shed_sensor";
}

// Talkpool OY1310
else if (
    sensorType === "water_meter_talkpool" ||
    sensorType === "talkpool_oy1310" ||
    model.includes("oy1310") ||
    manufacturer.includes("talkpool") ||
    profileName.toLowerCase().includes("oy1310")
) {
    deviceType = "water_meter_talkpool";
}

// Existing B Meters Hydrodigit
else if (
    sensorType === "water_meter_hydrodigit" ||
    model.includes("hydrodigit") ||
    manufacturer.includes("b meters") ||
    profileName === "B METERS HYDRODIGIT-S1 EU868"
) {
    deviceType = "water_meter_hydrodigit";
}

// Backwards compatibility:
// Existing devices tagged only as sensor_type=water_meter continue
// down the Hydrodigit path.
else if (
    sensorType === "water_meter"
) {
    deviceType = "water_meter_hydrodigit";
}

// ============================================================================
// Add normalized FAI metadata
// ============================================================================

msg.fai = {
    deviceType,
    eventType,

    devEui:
        String(
            deviceInfo.devEui || ""
        ).toUpperCase(),

    deviceName:
        String(
            deviceInfo.deviceName || ""
        ),

    profileName,
    tags
};

// ============================================================================
// Routing
// ============================================================================

// ShedSensor parser handles both uplinks and joins.
if (deviceType === "shed_sensor") {
    node.status({
        fill: "green",
        shape: "dot",
        text: `shed_sensor ${eventType}`
    });

    return [msg, null, null, null];
}

// Hydrodigit application uplinks.
if (
    deviceType === "water_meter_hydrodigit" &&
    eventType === "up"
) {
    node.status({
        fill: "blue",
        shape: "dot",
        text: "hydrodigit up"
    });

    return [null, msg, null, null];
}

// Talkpool OY1310 application uplinks.
if (
    deviceType === "water_meter_talkpool" &&
    (eventType === "up" || eventType === "join")
) {
    node.status({
        fill: "blue",
        shape: "dot",
        text: `OY1310 ${eventType}`
    });

    return [null, null, msg, null];
}

// Joins, unknown devices and unsupported events.
node.status({
    fill: "yellow",
    shape: "ring",
    text:
        `${deviceType || "unknown"} ${eventType}`
});

return [null, null, null, msg];

// ── FAI HYDRODIGIT LoRaWAN Raw Intake v1.0 ─────────────────────────────────
//
// Input:
//   ChirpStack /event/up message after the LoRaWAN dispatcher.
//
// Output:
//   A device-agnostic normalised raw LoRaWAN water-meter message.
//
// This node does not yet decode the proprietary HYDRODIGIT application
// payload. That section will be added once the payload specification or a
// real sample packet is available.

// ============================================================================
// Configuration
// ============================================================================

const gatewaySerial =
    env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

// Use a separate test topic until backend compatibility is confirmed.
const OUTPUT_TOPIC =
    `gateway/${gatewaySerial}/lorawan-watermeter/raw`;

// ============================================================================
// Validate ChirpStack message
// ============================================================================

const chirpstack =
    msg.payload || {};

const deviceInfo =
    chirpstack.deviceInfo || {};

if (
    !deviceInfo.devEui ||
    chirpstack.data === undefined ||
    chirpstack.data === null
) {
    node.warn(
        "Invalid HYDRODIGIT LoRaWAN message: " +
        "DevEUI or payload data is missing"
    );

    return null;
}

// ============================================================================
// Device metadata
// ============================================================================

const devEui =
    String(deviceInfo.devEui).toUpperCase();

const tags =
    deviceInfo.tags &&
    typeof deviceInfo.tags === "object"
        ? deviceInfo.tags
        : {};

const manufacturer =
    String(
        tags.manufacturer ||
        "B_METERS"
    );

const model =
    String(
        tags.model ||
        "HYDRODIGIT_S1"
    );

const meterSerial =
    String(
        tags.meter_serial ||
        tags.meterSerial ||
        deviceInfo.deviceName ||
        devEui
    );

const backendDeviceSerial =
    String(
        tags.backend_device_serial ||
        tags.backendDeviceSerial ||
        meterSerial
    );

// ============================================================================
// Decode raw LoRaWAN application payload
// ============================================================================

let rawBuffer;

try {
    if (Buffer.isBuffer(chirpstack.data)) {
        rawBuffer = chirpstack.data;
    } else {
        rawBuffer = Buffer.from(
            String(chirpstack.data),
            "base64"
        );
    }
} catch (error) {
    node.warn(
        `Unable to decode HYDRODIGIT payload from ${devEui}: ` +
        error.message
    );

    return null;
}

const rawBase64 =
    rawBuffer.toString("base64");

const rawHex =
    rawBuffer.toString("hex").toUpperCase();

// ============================================================================
// Radio metadata
// ============================================================================

let bestRssi = null;
let bestSnr = null;
let gatewayId = null;

if (
    Array.isArray(chirpstack.rxInfo) &&
    chirpstack.rxInfo.length > 0
) {
    const bestReception =
        chirpstack.rxInfo.reduce(
            (best, current) => {
                const currentRssi =
                    Number(current.rssi);

                const bestRssiValue =
                    Number(best.rssi);

                if (!Number.isFinite(bestRssiValue)) {
                    return current;
                }

                if (
                    Number.isFinite(currentRssi) &&
                    currentRssi > bestRssiValue
                ) {
                    return current;
                }

                return best;
            },
            chirpstack.rxInfo[0]
        );

    const candidateRssi =
        Number(bestReception.rssi);

    const candidateSnr =
        Number(bestReception.snr);

    bestRssi =
        Number.isFinite(candidateRssi)
            ? candidateRssi
            : null;

    bestSnr =
        Number.isFinite(candidateSnr)
            ? candidateSnr
            : null;

    gatewayId =
        bestReception.gatewayId || null;
}

// ============================================================================
// Timestamp
// ============================================================================

const receivedTimestamp =
    chirpstack.time ||
    new Date().toISOString();

// ============================================================================
// Normalised raw water-meter object
// ============================================================================

msg.waterMeter = {
    gatewaySerial,

    source: "lorawan",
    manufacturer,
    model,

    vendorDecoded:
        chirpstack.object &&
            typeof chirpstack.object === "object"
            ? chirpstack.object
            : null,

    devEui,
    meterSerial,
    backendDeviceSerial,

    timestamp: receivedTimestamp,

    lorawan: {
        applicationId:
            deviceInfo.applicationId || null,

        applicationName:
            deviceInfo.applicationName || null,

        deviceName:
            deviceInfo.deviceName || null,

        deviceProfileName:
            deviceInfo.deviceProfileName || null,

        devAddr:
            chirpstack.devAddr || null,

        frameCounter:
            Number.isInteger(
                Number(chirpstack.fCnt)
            )
                ? Number(chirpstack.fCnt)
                : null,

        fPort:
            Number.isInteger(
                Number(chirpstack.fPort)
            )
                ? Number(chirpstack.fPort)
                : null,

        confirmed:
            Boolean(chirpstack.confirmed),

        deduplicationId:
            chirpstack.deduplicationId || null
    },

    radio: {
        gatewayId,
        rssi: bestRssi,
        snr: bestSnr
    },

    raw: {
        base64: rawBase64,
        hex: rawHex,
        length: rawBuffer.length
    },

    // These fields will be populated by the actual HYDRODIGIT decoder.
    readings: {
        totalVolumeM3: null,
        intervalVolumeLitres: null,
        flowRateM3PerHour: null,
        waterTemperatureC: null
    },

    alarms: {
        leak: null,
        burst: null,
        reverseFlow: null,
        overflow: null,
        tamper: null,
        batteryLow: null
    }
};

// ============================================================================
// Temporary raw diagnostic output
// ============================================================================

msg.topic = OUTPUT_TOPIC;

msg.payload = {
    "_meta": {
        "received": receivedTimestamp,
        "receiver_id":
            gatewayId ||
            gatewaySerial,

        "rssi": bestRssi,
        "snr": bestSnr,
        "transport": "lorawan"
    },

    "data": {
        "DevEUI": devEui,
        "Manufacturer": manufacturer,
        "Model": model,
        "SerialNumber": meterSerial,
        "BackendDeviceSerial": backendDeviceSerial,
        "FPort": msg.waterMeter.lorawan.fPort,
        "FrameCounter":
            msg.waterMeter.lorawan.frameCounter,

        "PayloadLength":
            rawBuffer.length
    },

    "raw": rawBase64,
    "raw_hex": rawHex,
    "type": "lorawan_water_meter"
};

node.status({
    fill: "blue",
    shape: "dot",
    text:
        `${meterSerial}: ` +
        `${rawBuffer.length} bytes, ` +
        `port ${msg.waterMeter.lorawan.fPort}`
});

return msg;

// ── FAI HYDRODIGIT LoRaWAN Decoder v1.0 ─────────────────────────────────────
//
// Input:
//   msg.waterMeter from "HYDRODIGIT Raw Intake"
//
// Behaviour:
//   - Uses a ChirpStack decoded object when available.
//   - Preserves the original LoRaWAN payload.
//   - Produces a common water-meter structure.
//   - Does not fabricate readings when the payload format is unknown.
//
// Once the B METERS payload specification or a real packet is available,
// decodeHydrodigitRaw() can be completed without changing the rest of the flow.

// ============================================================================
// Validate input
// ============================================================================

if (
    !msg.waterMeter ||
    !msg.waterMeter.raw ||
    !msg.waterMeter.raw.base64
) {
    node.warn(
        "HYDRODIGIT Decoder: msg.waterMeter.raw is missing"
    );

    return null;
}

const meter = msg.waterMeter;

// ============================================================================
// Helpers
// ============================================================================

function getPath(object, path) {
    if (
        !object ||
        typeof object !== "object"
    ) {
        return undefined;
    }

    return path
        .split(".")
        .reduce(
            (value, key) =>
                value !== undefined &&
                value !== null
                    ? value[key]
                    : undefined,
            object
        );
}

function firstNumber(object, paths) {
    for (const path of paths) {
        const value =
            Number(getPath(object, path));

        if (Number.isFinite(value)) {
            return value;
        }
    }

    return null;
}

function firstBoolean(object, paths) {
    for (const path of paths) {
        const value =
            getPath(object, path);

        if (typeof value === "boolean") {
            return value;
        }

        if (
            value === 1 ||
            value === "1" ||
            String(value).toLowerCase() === "true"
        ) {
            return true;
        }

        if (
            value === 0 ||
            value === "0" ||
            String(value).toLowerCase() === "false"
        ) {
            return false;
        }
    }

    return null;
}

// ============================================================================
// Raw B METERS decoder placeholder
// ============================================================================
//
// Do not guess the HYDRODIGIT byte layout.
//
// This function will be replaced once we have:
//   - the B METERS LoRaWAN payload specification; or
//   - a real payload plus its confirmed decoded values.

function decodeHydrodigitRaw(rawBuffer, fPort) {
    if (!Buffer.isBuffer(rawBuffer)) {
        return null;
    }

    // HYDRODIGIT current-reading packets use FPort 1
    // and contain 9 bytes, or 11 when temperature is enabled.
    if (
        fPort !== 1 ||
        (rawBuffer.length !== 9 &&
         rawBuffer.length !== 11) ||
        rawBuffer[0] !== 0x45
    ) {
        return null;
    }

    // Byte 4 contains the upper nibble of both counters:
    // upper nibble = total-volume counter
    // lower nibble = reverse-flow counter
    const combinedCounterByte = rawBuffer[4];

    const totalVolumeLitres =
        rawBuffer[1] +
        (rawBuffer[2] * 0x100) +
        (rawBuffer[3] * 0x10000) +
        (((combinedCounterByte >> 4) & 0x0F) *
            0x1000000);

    const reverseFlowLitres =
        rawBuffer[5] +
        (rawBuffer[6] * 0x100) +
        (rawBuffer[7] * 0x10000) +
        ((combinedCounterByte & 0x0F) *
            0x1000000);

    const flags = rawBuffer[8];

    const decoded = {
        totalVolumeLitres,
        reverseFlowLitres,

        diameterMm:
            (flags & 0x40) !== 0
                ? 20
                : 15,

        medium:
            (flags & 0x80) !== 0
                ? "hot_water"
                : "cold_water",

        alarms: {
            leak:
                (flags & 0x01) !== 0,

            wrongInstallation:
                (flags & 0x02) !== 0,

            overflow:
                (flags & 0x04) !== 0,

            burst:
                (flags & 0x08) !== 0,

            reverseFlow:
                (flags & 0x10) !== 0,

            batteryLow:
                (flags & 0x20) !== 0
        }
    };

    if (rawBuffer.length === 11) {
        decoded.waterTemperatureC =
            rawBuffer.readInt16BE(9) / 10.0;
    }

    return decoded;
}

// ============================================================================
// Obtain decoded data
// ============================================================================

let decoded = null;

if (
    meter.vendorDecoded &&
    typeof meter.vendorDecoded === "object" &&
    !Array.isArray(meter.vendorDecoded)
) {
    decoded = meter.vendorDecoded;
} else {
    let rawBuffer;

    try {
        rawBuffer =
            Buffer.from(
                meter.raw.base64,
                "base64"
            );
    } catch (error) {
        node.warn(
            "HYDRODIGIT Decoder: invalid Base64 payload — " +
            error.message
        );

        return null;
    }

    decoded =
        decodeHydrodigitRaw(
            rawBuffer,
            meter.lorawan
                ? meter.lorawan.fPort
                : null
        );
}

// ============================================================================
// No decoder available yet
// ============================================================================

if (
    !decoded ||
    typeof decoded !== "object"
) {
    meter.decodeStatus = "raw_only";
    meter.decodeError =
        "HYDRODIGIT payload specification not yet configured";

    node.status({
        fill: "yellow",
        shape: "ring",
        text:
            `${meter.meterSerial || meter.devEui}: raw only`
    });

    node.warn(
        `HYDRODIGIT raw packet captured — ` +
        `device=${meter.devEui}, ` +
        `port=${meter.lorawan?.fPort ?? "unknown"}, ` +
        `length=${meter.raw.length}, ` +
        `hex=${meter.raw.hex}`
    );

    return msg;
}

// ============================================================================
// Normalise decoded values
// ============================================================================

// Prefer explicitly named cubic-metre fields.
let totalVolumeM3 =
    firstNumber(
        decoded,
        [
            "totalVolumeM3",
            "total_volume_m3",
            "total_m3",
            "volume_total_m3",
            "meter.totalVolumeM3",
            "meter.total_volume_m3"
        ]
    );

// Alternatively accept an explicitly named litre total.
if (totalVolumeM3 === null) {
    const totalVolumeLitres =
        firstNumber(
            decoded,
            [
                "totalVolumeLitres",
                "total_volume_l",
                "total_litres",
                "volume_total_l",
                "meter.totalVolumeLitres"
            ]
        );

    if (totalVolumeLitres !== null) {
        totalVolumeM3 =
            totalVolumeLitres / 1000.0;
    }
}

const intervalVolumeLitres =
    firstNumber(
        decoded,
        [
            "intervalVolumeLitres",
            "interval_volume_l",
            "delta_volume_l",
            "consumption_litres",
            "meter.intervalVolumeLitres"
        ]
    );

const flowRateM3PerHour =
    firstNumber(
        decoded,
        [
            "flowRateM3PerHour",
            "flow_rate_m3h",
            "flow_m3_h",
            "meter.flowRateM3PerHour"
        ]
    );

const waterTemperatureC =
    firstNumber(
        decoded,
        [
            "waterTemperatureC",
            "water_temperature_c",
            "temperature_c",
            "meter.waterTemperatureC"
        ]
    );

// ============================================================================
// Store normalised result
// ============================================================================

meter.vendorDecoded = decoded;

meter.readings = {
    totalVolumeM3,
    intervalVolumeLitres,
    flowRateM3PerHour,
    waterTemperatureC
};

meter.alarms = {
    leak:
        firstBoolean(
            decoded,
            [
                "leak",
                "leak_alarm",
                "alarms.leak"
            ]
        ),

    burst:
        firstBoolean(
            decoded,
            [
                "burst",
                "burst_alarm",
                "alarms.burst"
            ]
        ),

    reverseFlow:
        firstBoolean(
            decoded,
            [
                "reverseFlow",
                "reverse_flow",
                "alarms.reverseFlow"
            ]
        ),

    overflow:
        firstBoolean(
            decoded,
            [
                "overflow",
                "overflow_alarm",
                "alarms.overflow"
            ]
        ),

    tamper:
        firstBoolean(
            decoded,
            [
                "tamper",
                "tamper_alarm",
                "alarms.tamper"
            ]
        ),

    batteryLow:
        firstBoolean(
            decoded,
            [
                "batteryLow",
                "battery_low",
                "alarms.batteryLow"
            ]
        )
};

meter.decodeStatus =
    Number.isFinite(totalVolumeM3)
        ? "decoded"
        : "partial";

meter.decodeError =
    meter.decodeStatus === "decoded"
        ? null
        : "Decoded object did not contain a recognised total-volume field";

node.status({
    fill:
        meter.decodeStatus === "decoded"
            ? "green"
            : "yellow",

    shape:
        meter.decodeStatus === "decoded"
            ? "dot"
            : "ring",

    text:
        `${meter.meterSerial || meter.devEui}: ` +
        meter.decodeStatus
});

return msg;

// ── FAI LoRaWAN Water Meter Backend Formatter v1.0 ──────────────────────────
//
// Input:
//   msg.waterMeter from the HYDRODIGIT decoder.
//
// Output envelope:
//   _meta
//   data
//   raw
//   type
//
// This matches the general structure of the existing wM-Bus message without
// falsely labelling a LoRaWAN payload as wM-Bus.

// ============================================================================
// Configuration
// ============================================================================

const gatewaySerial =
    env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

const OUTPUT_TOPIC =
    `gateway/${gatewaySerial}/watermeter/out`;

// ============================================================================
// Validate input
// ============================================================================

if (!msg.waterMeter) {
    node.warn(
        "Water Meter Formatter: msg.waterMeter is missing"
    );

    return null;
}

const meter =
    msg.waterMeter;

if (
    meter.decodeStatus !== "decoded" ||
    !meter.readings ||
    !Number.isFinite(
        Number(meter.readings.totalVolumeM3)
    )
) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "waiting for decoded volume"
    });

    node.warn(
        `Water meter not sent to backend — ` +
        `device=${meter.devEui || "unknown"}, ` +
        `decodeStatus=${meter.decodeStatus || "unknown"}`
    );

    return null;
}

// ============================================================================
// Helpers
// ============================================================================

function nullableNumber(value) {
    const number =
        Number(value);

    return Number.isFinite(number)
        ? number
        : null;
}

function nullableBoolean(value) {
    return typeof value === "boolean"
        ? value
        : null;
}

// ============================================================================
// Build backend message
// ============================================================================

const receivedTimestamp =
    meter.timestamp ||
    new Date().toISOString();

const receiverId =
    meter.radio &&
    meter.radio.gatewayId
        ? meter.radio.gatewayId
        : gatewaySerial;

const meterSerial =
    String(
        meter.meterSerial ||
        meter.devEui ||
        "UNKNOWN_METER"
    );

const backendDeviceSerial =
    String(
        meter.backendDeviceSerial ||
        meterSerial
    );

msg.topic =
    OUTPUT_TOPIC;

msg.payload = {
    "_meta": {
        "received": receivedTimestamp,
        "receiver_id": receiverId,
        "rssi":
            meter.radio
                ? nullableNumber(
                    meter.radio.rssi
                )
                : null,

        "snr":
            meter.radio
                ? nullableNumber(
                    meter.radio.snr
                )
                : null,

        "transport": "lorawan"
    },

    "data": {
        "ID": backendDeviceSerial,

        "Manufacturer":
            meter.manufacturer ||
            "B_METERS",

        "Model":
            meter.model ||
            "HYDRODIGIT_S1",

        "SerialNumber":
            meterSerial,

        "DevEUI":
            meter.devEui || null,

        "TotalVolumeM3":
            nullableNumber(
                meter.readings.totalVolumeM3
            ),

        "IntervalVolumeLitres":
            nullableNumber(
                meter.readings.intervalVolumeLitres
            ),

        "FlowRateM3PerHour":
            nullableNumber(
                meter.readings.flowRateM3PerHour
            ),

        "WaterTemperatureC":
            nullableNumber(
                meter.readings.waterTemperatureC
            ),

        "LeakAlarm":
            nullableBoolean(
                meter.alarms?.leak
            ),

        "BurstAlarm":
            nullableBoolean(
                meter.alarms?.burst
            ),

        "ReverseFlowAlarm":
            nullableBoolean(
                meter.alarms?.reverseFlow
            ),

        "OverflowAlarm":
            nullableBoolean(
                meter.alarms?.overflow
            ),

        "TamperAlarm":
            nullableBoolean(
                meter.alarms?.tamper
            ),

        "BatteryLow":
            nullableBoolean(
                meter.alarms?.batteryLow
            ),

        "FPort":
            meter.lorawan
                ? nullableNumber(
                    meter.lorawan.fPort
                )
                : null,

        "FrameCounter":
            meter.lorawan
                ? nullableNumber(
                    meter.lorawan.frameCounter
                )
                : null
    },

    "raw":
        meter.raw.base64,

    "type":
        "water_meter"
};

node.status({
    fill: "green",
    shape: "dot",
    text:
        `${meterSerial}: ` +
        `${meter.readings.totalVolumeM3} m³`
});

return msg;

function validUnit(v){ return Number.isInteger(v) && v >= 1 && v <= 96; }
function validChannels(v){ return Number.isInteger(v) && v >= 1 && v <= 10; }

let s1 = Number(env.get('ADS301_SILO_1_ACCESS_UNIT_ID') || 0);
let s2 = Number(env.get('ADS301_SILO_2_ACCESS_UNIT_ID') || 0);
let c1 = Number(env.get('ADS301_SILO_1_CHANNELS') || 4);
let c2 = Number(env.get('ADS301_SILO_2_CHANNELS') || 4);

if (!validUnit(s1)) s1 = 0;
if (!validUnit(s2)) s2 = 0;
if (!validChannels(c1)) c1 = 4;
if (!validChannels(c2)) c2 = 4;

flow.set('ads301Silo1AccessUnitId', s1);
flow.set('ads301Silo2AccessUnitId', s2);
flow.set('ads301Silo1Channels', c1);
flow.set('ads301Silo2Channels', c2);

flow.set('ads301MapCandidate1', s1);
flow.set('ads301MapCandidate2', s2);
flow.set('ads301ChannelsCandidate1', c1);
flow.set('ads301ChannelsCandidate2', c2);

const zero1 = flow.get('ads301LastZeroSilo1');
const zero2 = flow.get('ads301LastZeroSilo2');

const zeroText = record => record?.timestamp
    ? `${record.timestamp} UTC — Access Unit ${record.unitId}; raw sum ${record.rawSum}`
    : 'No software zero recorded in this Node-RED context.';

const mapText =
    `ADS301 mapping loaded: ` +
    `Silo 1 = ${s1 ? `Access Unit ${s1}, ${c1} channels` : 'NOT SET'}; ` +
    `Silo 2 = ${s2 ? `Access Unit ${s2}, ${c2} channels` : 'NOT SET'}.`;

return [
  {payload:s1 || ''},
  {payload:s2 || ''},
  {payload:mapText},
  {payload:zeroText(zero1)},
  {payload:zeroText(zero2)},
  {payload:c1},
  {payload:c2}
];

const value = Number(String(msg.payload ?? '').trim());
flow.set('ads301MapCandidate1', value);
return null;

const value = Number(String(msg.payload ?? '').trim());
flow.set('ads301MapCandidate2', value);
return null;

const s1 = Number(flow.get('ads301MapCandidate1')) || 0;
const s2 = Number(flow.get('ads301MapCandidate2')) || 0;
const c1 = Number(flow.get('ads301ChannelsCandidate1'));
const c2 = Number(flow.get('ads301ChannelsCandidate2'));

const validUnit = v => Number.isInteger(v) && v >= 1 && v <= 96;
const validChannels = v => Number.isInteger(v) && v >= 1 && v <= 10;

msg.requestPurpose = 'mapping';

if (s1 !== 0 && !validUnit(s1)) {
  msg.payload = '✗ Silo 1 Access Unit must be blank or an integer from 1 to 96.';
  return msg;
}
if (s2 !== 0 && !validUnit(s2)) {
  msg.payload = '✗ Silo 2 Access Unit must be blank or an integer from 1 to 96.';
  return msg;
}
if (s1 === 0 && s2 === 0) {
  msg.payload = '✗ Set at least one ADS301 Access Unit ID.';
  return msg;
}
if (s1 !== 0 && s2 !== 0 && s1 === s2) {
  msg.payload = '✗ Silo 1 and Silo 2 cannot use the same Access Unit when both boxes are connected.';
  return msg;
}
if (s1 !== 0 && !validChannels(c1)) {
  msg.payload = '✗ Silo 1 active channel count must be 1 to 10.';
  return msg;
}
if (s2 !== 0 && !validChannels(c2)) {
  msg.payload = '✗ Silo 2 active channel count must be 1 to 10.';
  return msg;
}

flow.set('ads301Silo1AccessUnitId', s1);
flow.set('ads301Silo2AccessUnitId', s2);
flow.set('ads301Silo1Channels', validChannels(c1) ? c1 : 4);
flow.set('ads301Silo2Channels', validChannels(c2) ? c2 : 4);

msg.payload =
  `✓ ADS301 mapping applied: ` +
  `Silo 1 = ${s1 ? `Access Unit ${s1}, ${c1} channels` : 'NOT SET'}; ` +
  `Silo 2 = ${s2 ? `Access Unit ${s2}, ${c2} channels` : 'NOT SET'}.`;
return msg;

const value = Number(String(msg.payload ?? '').trim());
flow.set('ads301CurrentAddress', value);
return null;

const value = Number(String(msg.payload ?? '').trim());
flow.set('ads301NewAddress', value);
return null;

const current = Number(flow.get('ads301CurrentAddress'));
const next = Number(flow.get('ads301NewAddress'));
const isolated = flow.get('ads301AddressIsolated') === true;
const valid = v => Number.isInteger(v) && v >= 1 && v <= 96;

if (!valid(current) || !valid(next)) {
    return [null,{requestPurpose:'addressing',payload:'Current and new addresses must be integers from 1 to 96.'}];
}
if (current === next) {
    return [null,{requestPurpose:'addressing',payload:'Current and new addresses are the same.'}];
}
if (!isolated) {
    return [null,{requestPurpose:'addressing',payload:'Do not continue: isolate the target junction box from any other device that may use the same current address.'}];
}
if (flow.get('ads301BusBusy')) {
    return [null,{requestPurpose:'addressing',payload:'ADS301 bus operation already running.'}];
}

flow.set('ads301BusBusy', true);

const common = {
    oldUnitId: current,
    newUnitId: next,
    requestPurpose: 'addressing'
};

return [[
    {
        ...common,
        modbusAction:'write',
