            fill: "blue",
            shape: "ring",
            text: `new session ${joinDevEui.slice(-8)}`
        });
    }

    return null;
}

if (eventType !== "up") {
    return null;
}

// ============================================================================
// Validate incoming ChirpStack message
// ============================================================================

if (
    !msg.payload ||
    !msg.payload.deviceInfo ||
    !msg.payload.deviceInfo.devEui ||
    msg.payload.data === undefined ||
    msg.payload.data === null
) {
    node.warn(
        "Invalid ChirpStack message: required payload fields are missing"
    );

    return null;
}

// ============================================================================
// Device identity
// ============================================================================

const devEui =
    String(
        msg.payload.deviceInfo.devEui
    ).toUpperCase();

const uidHex =
    devEui.slice(-8);

if (!/^[0-9A-F]{8}$/.test(uidHex)) {
    node.warn(
        `Invalid DevEUI: ${devEui}`
    );

    return null;
}

const dynamicUid =
    parseInt(uidHex, 16);

if (!Number.isFinite(dynamicUid)) {
    node.warn(
        `Unable to calculate UID from DevEUI: ${devEui}`
    );

    return null;
}

// ============================================================================
// Decode compact LoRaWAN payload
// ============================================================================

let buf;

try {
    if (Buffer.isBuffer(msg.payload.data)) {
        buf = msg.payload.data;
    } else {
        buf = Buffer.from(
            String(msg.payload.data),
            "base64"
        );
    }
} catch (error) {
    node.warn(
        `Unable to decode LoRa payload from ${devEui}: ` +
        error.message
    );

    return null;
}

if (buf.length < 1) {
    node.warn(
        `Empty LoRa payload from ${devEui}`
    );

    return null;
}

const protocolVersion =
    buf.readUInt8(0);

const fPortCandidate =
    msg.payload.fPort !== undefined
        ? msg.payload.fPort
        : (
            msg.payload.fport !== undefined
                ? msg.payload.fport
                : msg.payload.port
        );

const fPort =
    Number(fPortCandidate);

if (
    !Number.isInteger(fPort) ||
    fPort < 1 ||
    fPort > 223
) {
    node.warn(
        `Missing/invalid FPort from ${devEui}: ` +
        `${String(fPortCandidate)}`
    );

    return null;
}

// ============================================================================
// Identify and validate packet format
// ============================================================================

let packetKind = null;
let packetSequence = null;

if (
    protocolVersion === V2_VERSION &&
    fPort === V2_WEIGHT_PORT
) {
    if (
        buf.length !==
        V2_WEIGHT_PAYLOAD_LENGTH
    ) {
        node.warn(
            `Unexpected V2 weight payload length from ${devEui}: ` +
            `${buf.length} bytes; expected ${V2_WEIGHT_PAYLOAD_LENGTH}`
        );

        return null;
    }

    const sampleCount =
        buf.readUInt8(1);

    if (
        sampleCount !==
        V2_WEIGHT_SAMPLE_COUNT
    ) {
        node.warn(
            `Invalid V2 weight sample count from ${devEui}: ` +
            `${sampleCount}; expected ${V2_WEIGHT_SAMPLE_COUNT}`
        );

        return null;
    }

    packetKind = "v2-weight";
    packetSequence =
        buf.readUInt16LE(2);
}
else if (
    protocolVersion === V2_VERSION &&
    fPort === V2_ENVIRONMENT_PORT
) {
    if (
        buf.length !==
        V2_ENVIRONMENT_PAYLOAD_LENGTH
    ) {
        node.warn(
            `Unexpected V2 environment payload length from ${devEui}: ` +
            `${buf.length} bytes; expected ${V2_ENVIRONMENT_PAYLOAD_LENGTH}`
        );

        return null;
    }

    packetKind = "v2-environment";
    packetSequence =
        buf.readUInt16LE(1);
}
else if (
    protocolVersion === V1_VERSION &&
    fPort === V1_PORT
) {
    if (
        buf.length !==
        V1_PAYLOAD_LENGTH
    ) {
        node.warn(
            `Unexpected V1 payload length from ${devEui}: ` +
            `${buf.length} bytes; expected ${V1_PAYLOAD_LENGTH}`
        );

        return null;
    }

    const sampleCount =
        buf.readUInt8(1);

    if (
        sampleCount === 0 ||
        sampleCount >
        V1_MAX_WEIGHT_SAMPLES
    ) {
        node.warn(
            `Invalid V1 weight sample count from ${devEui}: ` +
            sampleCount
        );

        return null;
    }

    packetKind = "v1-combined";
    packetSequence =
        buf.readUInt16LE(2);
}
else {
    node.warn(
        `Unsupported LoRa application packet — ` +
        `device=${devEui}, ` +
        `version=${protocolVersion}, ` +
        `fPort=${fPort}, ` +
        `length=${buf.length}`
    );

    return null;
}

// ============================================================================
// Session-aware duplicate protection
// ============================================================================
//
// The application counters and LoRaWAN frame counter can restart after OTAA.
// Therefore duplicate protection is scoped to the detected LoRaWAN session.

const stateKey =
    `${STATE_NAMESPACE}_state_${devEui}`;

let deviceState =
    global.get(stateKey);

if (
    !deviceState ||
    typeof deviceState !== "object" ||
    Array.isArray(deviceState)
) {
    deviceState = {
        sessionSequence: 0,
        devAddr: null,
        maxFrameCounter: -1,
        recentEventIds: [],
        recentPackets: []
    };
}

if (
    !Array.isArray(
        deviceState.recentEventIds
    )
) {
    deviceState.recentEventIds = [];
}

if (
    !Array.isArray(
        deviceState.recentPackets
    )
) {
    deviceState.recentPackets = [];
}

const normaliseHex = value =>
    String(value || "")
        .replace(/^0x/i, "")
        .replace(/[^0-9a-f]/gi, "")
        .toUpperCase();

const devAddr =
    normaliseHex(
        msg.payload.devAddr
    );

const frameCounter =
    Number(
        msg.payload.fCnt
    );

const hasFrameCounter =
    Number.isInteger(frameCounter) &&
    frameCounter >= 0;

const devAddrChanged =
    devAddr.length > 0 &&
    deviceState.devAddr &&
    devAddr !== deviceState.devAddr;

const frameCounterRestarted =
    hasFrameCounter &&
    frameCounter <= 1 &&
    Number.isInteger(
        deviceState.maxFrameCounter
    ) &&
    deviceState.maxFrameCounter > 1;

if (
    devAddrChanged ||
    frameCounterRestarted
) {
    deviceState.sessionSequence =
        Number(
            deviceState.sessionSequence || 0
        ) + 1;

    deviceState.recentEventIds = [];
    deviceState.recentPackets = [];
    deviceState.maxFrameCounter = -1;

    node.warn(
        `New LoRaWAN session detected — ` +
        `device=${devEui}, ` +
        `devAddr=${devAddr || "unknown"}, ` +
        `fCnt=${hasFrameCounter ? frameCounter : "unknown"}`
    );
}

if (devAddr.length > 0) {
    deviceState.devAddr =
        devAddr;
}

const payloadHex =
    buf.toString("hex");

const deduplicationId =
    String(
        msg.payload.deduplicationId || ""
    ).trim();

const exactEventSignature =
    deduplicationId
        ? `dedup:${deduplicationId}`
        : (
            devAddr.length > 0 &&
            hasFrameCounter
                ? (
                    `frame:${devAddr}:` +
                    `${frameCounter}:` +
                    `${fPort}:` +
                    `${payloadHex}`
                )
                : (
                    `payload:${fPort}:` +
                    `${packetSequence}:` +
                    `${payloadHex}`
                )
        );

if (
    deviceState.recentEventIds.includes(
        exactEventSignature
    )
) {
    node.warn(
        `Ignoring duplicate ChirpStack event — ` +
        `device=${devEui}, ` +
        `kind=${packetKind}, ` +
        `sequence=${packetSequence}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `duplicate ${packetKind} ${packetSequence}`
    });

    return null;
}

const sessionIdentity =
    `session:${Number(deviceState.sessionSequence || 0)}:` +
    `${deviceState.devAddr || "unknown"}`;

const applicationPacketSignature =
    `${sessionIdentity}:` +
    `${packetKind}:` +
    `${packetSequence}:` +
    `${payloadHex}`;

if (
    deviceState.recentPackets.includes(
        applicationPacketSignature
    )
) {
    node.warn(
        `Ignoring retransmitted application packet — ` +
        `device=${devEui}, ` +
        `kind=${packetKind}, ` +
        `sequence=${packetSequence}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `retransmitted ${packetKind} ${packetSequence}`
    });

    return null;
}

deviceState.recentEventIds.push(
    exactEventSignature
);

deviceState.recentPackets.push(
    applicationPacketSignature
);

if (
    deviceState.recentEventIds.length >
    RECENT_MESSAGE_HISTORY
) {
    deviceState.recentEventIds =
        deviceState.recentEventIds.slice(
            -RECENT_MESSAGE_HISTORY
        );
}

if (
    deviceState.recentPackets.length >
    RECENT_MESSAGE_HISTORY
) {
    deviceState.recentPackets =
        deviceState.recentPackets.slice(
            -RECENT_MESSAGE_HISTORY
        );
}

if (hasFrameCounter) {
    deviceState.maxFrameCounter =
        Math.max(
            Number(
                deviceState.maxFrameCounter || -1
            ),
            frameCounter
        );
}

global.set(
    stateKey,
    deviceState
);

// ============================================================================
// RSSI
// ============================================================================

let bestRssi = -120;

if (
    Array.isArray(
        msg.payload.rxInfo
    ) &&
    msg.payload.rxInfo.length > 0
) {
    const validRssiValues =
        msg.payload.rxInfo
            .map(
                rx => Number(rx.rssi)
            )
            .filter(
                value => Number.isFinite(value)
            );

    if (
        validRssiValues.length > 0
    ) {
        bestRssi =
            Math.max(
                ...validRssiValues
            );
    }
}

const rawRssi =
    Math.abs(bestRssi);

// ============================================================================
// Timestamp helpers
// ============================================================================
//
// As in the previous proven parser, Node-RED processing time is used as the
// packet timestamp. V2 firmware does not currently transmit an RTC timestamp.

function formatBackendTimestamp(date) {
    return (
        date.toISOString().split(".")[0] +
        "+00:00"
    );
}

const receivedTime =
    new Date();

const receivedTimestamp =
    formatBackendTimestamp(
        receivedTime
    );

// ============================================================================
// Backend message helpers
// ============================================================================

const outMessages = [];

const usedPacketNumbers =
    new Set();

function nextPacketNumber() {
    let packetNumber;

    do {
        packetNumber =
            Math.floor(
                Math.random() * 65536
            );
    } while (
        usedPacketNumbers.has(
            packetNumber
        )
    );

    usedPacketNumbers.add(
        packetNumber
    );

    return packetNumber;
}

function makeBackendMessage(
    hexData,
    timestamp
) {
    return {
        topic:
            `gateway/${gatewaySerial}/tinymesh/out`,

        payload: {
            "_meta": {
                "received": timestamp
            },

            "block": 0,
            "data": hexData,
            "detail": "serial",
            "hops": 1,
            "latency": 2,
            "network_lvl": 1,
            "packet_num": nextPacketNumber(),
            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    };
}

// ============================================================================
// Legacy Type 0x01 environmental packet
// ============================================================================
//
// Type:      0x01
// Length:    58 bytes
// Signature: 013a

function makeEnvironmentMessage(
    temperature,
    pressure,
    humidity,
    lux,
    co2,
    timestamp
) {
    const envBuf =
        Buffer.alloc(58, 0);

    envBuf.writeUInt8(
        0x01,
        0
    );

    envBuf.writeUInt8(
        0x3A,
        1
    );

    // Bytes 2-5 remain reserved and zero-filled.

    envBuf.writeFloatLE(
        temperature,
        6
    );                                      // AirTemperature

    envBuf.writeFloatLE(
        pressure,
        10
    );                                      // AirPressure

    envBuf.writeFloatLE(
        temperature,
        14
    );                                      // HumidityTemperature

    envBuf.writeFloatLE(
        humidity,
        18
    );                                      // Humidity

    envBuf.writeUInt32LE(
        Math.min(
            0xFFFFFFFF,
            Math.max(
                0,
                Math.round(lux)
            )
        ),
        22
    );                                      // LightALS

    // Confirmed backend workaround retained from v9.1:
    // GASCO2 must be UInt32, not Float32.
    envBuf.writeUInt32LE(
        Math.min(
            0xFFFFFFFF,
            Math.max(
                0,
                Math.round(co2)
            )
        ),
        26
    );                                      // GASCO2

    envBuf.writeFloatLE(
        0.0,
        30
    );                                      // GASTemperature

    envBuf.writeFloatLE(
        0.0,
        34
    );                                      // GASHumidity

    envBuf.writeFloatLE(
        0.0,
        38
    );                                      // GASNH3

    envBuf.writeFloatLE(
        0.0,
        42
    );                                      // GASCO

    envBuf.writeFloatLE(
        0.0,
        46
    );                                      // GASNO2

    envBuf.writeFloatLE(
        temperature,
        50
    );                                      // BoardTemperature

    envBuf.writeFloatLE(
        temperature,
        54
    );                                      // PT100Temperature

    return makeBackendMessage(
        envBuf.toString("hex"),
        timestamp
    );
}

// ============================================================================
// Legacy Type 0x02 weight packet
// ============================================================================
//
// Type:      0x02
// Length:    106 bytes
// Signature: 026a

function makeWeightMessage(
    legacySamples,
    timestamp
) {
    const wBuf =
        Buffer.alloc(106, 0);

    wBuf.writeUInt8(
        0x02,
        0
    );

    wBuf.writeUInt8(
        0x6A,
        1
    );

    // Bytes 2-5 remain reserved and zero-filled.

    for (
        let i = 0;
        i < LEGACY_WEIGHT_SAMPLE_COUNT;
        i++
    ) {
        const value =
            Math.min(
                65534,
                Math.max(
                    0,
                    Math.round(
                        legacySamples[i] || 0
                    )
                )
            );

        wBuf.writeUInt16LE(
            value,
            6 + (i * 2)
        );
    }

    return makeBackendMessage(
        wBuf.toString("hex"),
        timestamp
    );
}

// ============================================================================
// V2 weight waveform helpers
// ============================================================================

function repairInvalidWeightSamples(
    sourceSamples
) {
    const repaired =
        sourceSamples.slice();

    let repairedCount = 0;

    for (
        let i = 0;
        i < repaired.length;
        i++
    ) {
        if (
            repaired[i] !==
            INVALID_WEIGHT
        ) {
            continue;
        }

        repairedCount++;

        let replacement = null;

        for (
            let distance = 1;
            distance < repaired.length;
            distance++
        ) {
            const leftIndex =
                i - distance;

            const rightIndex =
                i + distance;

            if (
                leftIndex >= 0 &&
                repaired[leftIndex] !==
                INVALID_WEIGHT
            ) {
                replacement =
                    repaired[leftIndex];

                break;
            }

            if (
                rightIndex <
                    repaired.length &&
                repaired[rightIndex] !==
                    INVALID_WEIGHT
            ) {
                replacement =
                    repaired[rightIndex];

                break;
            }
        }

        repaired[i] =
            replacement === null
                ? 0
                : replacement;
    }

    return {
        samples: repaired,
        repairedCount
    };
}

function expandV2WeightToLegacy(
    sourceSamples
) {
    const repairedResult =
        repairInvalidWeightSamples(
            sourceSamples
        );

    const source =
        repairedResult.samples;

    const legacy =
        new Array(
            LEGACY_WEIGHT_SAMPLE_COUNT
        );

    // Nearest-neighbour resampling:
    //
    //   source index 0  -> legacy index 0
    //   source index 22 -> legacy index 49
    //
    // This preserves measured values rather than inventing interpolated
    // amplitudes. It only repeats measured points to populate the fixed
    // 50-value historical structure.

    for (
        let legacyIndex = 0;
        legacyIndex <
            LEGACY_WEIGHT_SAMPLE_COUNT;
        legacyIndex++
    ) {
        const sourcePosition =
            legacyIndex *
            (source.length - 1) /
            (
                LEGACY_WEIGHT_SAMPLE_COUNT -
                1
            );

        const sourceIndex =
            Math.round(
                sourcePosition
            );

        legacy[legacyIndex] =
            source[sourceIndex];
    }

    return {
        samples: legacy,
        repairedCount:
            repairedResult.repairedCount
    };
}

// ============================================================================
// Decode packet
// ============================================================================

if (packetKind === "v2-weight") {
    const sampleCount =
        buf.readUInt8(1);

    const eventNumber =
        buf.readUInt16LE(2);

    const sourceSamples = [];

    for (
        let i = 0;
        i < sampleCount;
        i++
    ) {
        sourceSamples.push(
            buf.readUInt16LE(
                4 + (i * 2)
            )
        );
    }

    const expanded =
        expandV2WeightToLegacy(
            sourceSamples
        );

    outMessages.push(
        makeWeightMessage(
            expanded.samples,
            receivedTimestamp
        )
    );

    const validSourceSamples =
        sourceSamples.filter(
            value =>
                value !== INVALID_WEIGHT
        );

    const sourceMinimum =
        validSourceSamples.length > 0
            ? Math.min(
                ...validSourceSamples
            )
            : null;

    const sourceMaximum =
        validSourceSamples.length > 0
            ? Math.max(
                ...validSourceSamples
            )
            : null;

    node.warn(
        `V2 WEIGHT EVENT DECODED — ` +
        `device=${devEui}, ` +
        `event=${eventNumber}, ` +
        `samples=${sampleCount}, ` +
        `min=${sourceMinimum === null ? "none" : sourceMinimum}, ` +
        `max=${sourceMaximum === null ? "none" : sourceMaximum}, ` +
        `repairedInvalid=${expanded.repairedCount}, ` +
        `backendMessages=1`
    );

    node.status({
        fill:
            expanded.repairedCount > 0
                ? "yellow"
                : "green",

        shape: "dot",

        text:
            `weight event ${eventNumber} -> 1 backend packet`
    });
}
else if (
    packetKind === "v2-environment"
) {
    const environmentPacketNumber =
        buf.readUInt16LE(1);

    const temperature =
        buf.readInt16LE(3) /
        100.0;

    const co2 =
        buf.readUInt16LE(5);

    const lux =
        buf.readUInt16LE(7);

    const humidity =
        buf.readUInt16LE(9) /
        100.0;

    const pressure =
        buf.readUInt16LE(11) /
        10.0;

    outMessages.push(
        makeEnvironmentMessage(
            temperature,
            pressure,
            humidity,
            lux,
            co2,
            receivedTimestamp
        )
    );

    node.warn(
        `V2 ENVIRONMENT DECODED — ` +
        `device=${devEui}, ` +
        `packet=${environmentPacketNumber}, ` +
        `temperature=${temperature}, ` +
        `pressure=${pressure}, ` +
        `humidity=${humidity}, ` +
        `lux=${lux}, ` +
        `co2=${co2}, ` +
        `backendMessages=1`
    );

    node.status({
        fill: "green",
        shape: "dot",
        text:
            `environment ${environmentPacketNumber} -> 1 backend packet`
    });
}
else if (
    packetKind === "v1-combined"
) {
    // ------------------------------------------------------------------------
    // Backward-compatible path for the old combined V1 packet.
    // This deliberately preserves the v9.1 behaviour.
    // ------------------------------------------------------------------------

    const sampleCount =
        buf.readUInt8(1);

    const batchNumber =
        buf.readUInt16LE(2);

    const temperature =
        buf.readInt16LE(40) /
        100.0;

    const co2 =
        buf.readUInt16LE(42);

    const lux =
        buf.readUInt16LE(44);

    const humidity =
        buf.readUInt16LE(46) /
        100.0;

    const pressure =
        buf.readUInt16LE(48) /
        10.0;

    let validWeightEvents = 0;
    let invalidWeightEvents = 0;
    let genuineZeroEvents = 0;

    const newestSampleTime =
        receivedTime;

    for (
        let i = 0;
        i < sampleCount;
        i++
    ) {
        const weight =
            buf.readUInt16LE(
                4 + (i * 2)
            );

        const ageFromNewestMs =
            (
                sampleCount -
                1 -
                i
            ) *
            V1_WEIGHT_INTERVAL_MS;

        const sampleTime =
            new Date(
                newestSampleTime.getTime() -
                ageFromNewestMs
            );

        const sampleTimestamp =
            formatBackendTimestamp(
                sampleTime
            );

        if (
            weight ===
            INVALID_WEIGHT
        ) {
            invalidWeightEvents++;

            continue;
        }

        const outputWeight =
            Math.min(
                65534,
                Math.max(
                    0,
                    Math.round(weight)
                )
            );

        if (
            outputWeight === 0
        ) {
            genuineZeroEvents++;
        }

        const legacySamples =
            new Array(
                LEGACY_WEIGHT_SAMPLE_COUNT
            ).fill(
                outputWeight
            );

        outMessages.push(
            makeWeightMessage(
                legacySamples,
                sampleTimestamp
            )
        );

        validWeightEvents++;
    }

    outMessages.push(
        makeEnvironmentMessage(
            temperature,
            pressure,
            humidity,
            lux,
            co2,
            receivedTimestamp
        )
    );

    node.warn(
        `V1 COMBINED BATCH DECODED — ` +
        `device=${devEui}, ` +
        `batch=${batchNumber}, ` +
        `samples=${sampleCount}, ` +
        `validWeights=${validWeightEvents}, ` +
        `invalidWeights=${invalidWeightEvents}, ` +
        `genuineZeros=${genuineZeroEvents}, ` +
        `backendMessages=${outMessages.length}`
    );

    node.status({
        fill:
            invalidWeightEvents > 0
                ? "yellow"
                : "green",

        shape: "dot",

        text:
            `${validWeightEvents} V1 weights + 1 env`
    });
}

// ============================================================================
// Send all generated backend messages through output 1
// ============================================================================

if (outMessages.length === 0) {
    return null;
}

node.send(
    [outMessages]
);

return null;

// ── FAI LoRaWAN Device Dispatcher v1.1 ─────────────────────────────────────
//
// Output 1: ShedSensor events, including up and join
// Output 2: Water-meter uplinks only
// Output 3: Water-meter joins and unknown devices/events

const payload =
    msg.payload || {};

const deviceInfo =
    payload.deviceInfo || {};

const tags =
    deviceInfo.tags &&
    typeof deviceInfo.tags === "object"
        ? deviceInfo.tags
        : {};

const profileName =
    String(
        deviceInfo.deviceProfileName || ""
    );

const eventType =
    String(msg.topic || "")
        .split("/")
        .filter(Boolean)
        .pop() || "unknown";

let deviceType =
    String(
        tags.sensor_type ||
        tags.device_type ||
        ""
    ).toLowerCase();

// Compatibility with existing profiles that do not yet have tags.
if (!deviceType) {
    if (profileName === "RAK3272 Node") {
        deviceType = "shed_sensor";
    } else if (
        profileName ===
        "B METERS HYDRODIGIT-S1 EU868"
    ) {
        deviceType = "water_meter";
    }
}

msg.fai = {
    deviceType,
    eventType,

    devEui:
        String(
            deviceInfo.devEui || ""
        ).toUpperCase(),

    deviceName:
        String(
            deviceInfo.deviceName || ""
        ),

    profileName,
    tags
};

// ShedSensor parser handles both uplinks and joins.
if (deviceType === "shed_sensor") {
    node.status({
        fill: "green",
        shape: "dot",
        text: `shed_sensor ${eventType}`
    });

    return [msg, null, null];
}

// Only water-meter uplinks contain application payload data.
if (
    deviceType === "water_meter" &&
    eventType === "up"
) {
    node.status({
        fill: "blue",
        shape: "dot",
        text: "water_meter up"
    });

    return [null, msg, null];
}

// Water-meter join events and unidentified devices go to diagnostics.
node.status({
    fill: "yellow",
    shape: "ring",
    text:
        `${deviceType || "unknown"} ${eventType}`
});

return [null, null, msg];

// ── FAI Talkpool OY1310 Parser v1.0 ────────────────────────────────────────
//
// Input:
//   ChirpStack application/.../event/up message
//   routed from LoRa Device Dispatcher output 3.
//
// Supported OY1310 uplinks:
//
//   Measurement:
//     FPort: 1
//     6 bytes
//     01 21 XX XX XX XX
//     bytes 2-5 = UInt32 BE accumulated volume in litres
//
//   Status:
//     FPort: 1
//     3 bytes
//     01 20 XX
//
// Output:
//   Normalised Talkpool water-meter message.
//   Backend formatting is intentionally handled separately.

const payload =
    msg.payload || {};

const deviceInfo =
    payload.deviceInfo || {};

const devEui =
    String(
        deviceInfo.devEui ||
        (msg.fai && msg.fai.devEui) ||
        ""
    ).toUpperCase();

const deviceName =
    String(
        deviceInfo.deviceName ||
        (msg.fai && msg.fai.deviceName) ||
        devEui
    );

const fPort =
    Number(payload.fPort);

// --------------------------------------------------------------------------
// Validate LoRaWAN port
// --------------------------------------------------------------------------
const eventType =
    msg.fai?.eventType ||
    String(msg.topic || "")
        .split("/")
        .filter(Boolean)
        .pop();

if (eventType !== "up") {
    return null;
}

if (fPort !== 1) {
    node.warn(
        `OY1310 unexpected FPort — ` +
        `device=${devEui || "unknown"}, ` +
        `fPort=${fPort}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `unexpected FPort ${fPort}`
    });

    return null;
}

// --------------------------------------------------------------------------
// Decode ChirpStack Base64 application payload
// --------------------------------------------------------------------------

let buf;

try {
    if (Buffer.isBuffer(payload.data)) {
        buf = payload.data;
    } else {
        buf = Buffer.from(
            String(payload.data || ""),
            "base64"
        );
    }
} catch (error) {
    node.warn(
        `OY1310 payload decode failed — ` +
        `device=${devEui || "unknown"}, ` +
        `error=${error.message}`
    );

    node.status({
        fill: "red",
        shape: "ring",
        text: "payload decode failed"
    });

    return null;
}

if (buf.length < 2) {
    node.warn(
        `OY1310 payload too short — ` +
        `device=${devEui || "unknown"}, ` +
        `length=${buf.length}`
    );

    return null;
}

const type =
    buf.readUInt8(0);

const index =
    buf.readUInt8(1);

const rawHex =
    buf.toString("hex");

// --------------------------------------------------------------------------
// Validate Talkpool protocol type
//
// 0x01 = Data
// --------------------------------------------------------------------------

if (type !== 0x01) {
    node.warn(
        `OY1310 unsupported message type — ` +
        `device=${devEui || "unknown"}, ` +
        `type=0x${type.toString(16).padStart(2, "0")}, ` +
        `raw=${rawHex}`
    );

    return null;
}

// --------------------------------------------------------------------------
// 0x21 — accumulated volume
//
// Expected:
//   01 21 XX XX XX XX
//
// UInt32 big-endian, litres.
// --------------------------------------------------------------------------

if (index === 0x21) {

    if (buf.length !== 6) {
        node.warn(
            `OY1310 invalid volume payload length — ` +
            `device=${devEui || "unknown"}, ` +
            `length=${buf.length}, expected=6, ` +
            `raw=${rawHex}`
        );

        node.status({
            fill: "red",
            shape: "ring",
            text: `bad volume length ${buf.length}`
        });

        return null;
    }

    const volumeLitres =
        buf.readUInt32BE(2);

    const volumeM3 =
        volumeLitres / 1000.0;

    // Best RSSI from ChirpStack gateway reception metadata.
    let rssi = null;

    if (
        Array.isArray(payload.rxInfo) &&
        payload.rxInfo.length > 0
    ) {
        const values =
            payload.rxInfo
                .map(rx => Number(rx.rssi))
                .filter(Number.isFinite);

        if (values.length > 0) {
            rssi = Math.max(...values);
        }
    }

    msg.payload = {
        manufacturer: "Talkpool",
        model: "OY1310",

        dev_eui: devEui,
        device_name: deviceName,

        volume_litres: volumeLitres,
        volume_m3: volumeM3,

        f_port: fPort,
        frame_counter:
            Number.isFinite(Number(payload.fCnt))
                ? Number(payload.fCnt)
                : null,

        rssi,

        timestamp:
            payload.time ||
            new Date().toISOString(),

        raw: rawHex
    };

    msg.fai = {
        ...(msg.fai || {}),
        deviceType: "water_meter_talkpool",
        manufacturer: "Talkpool",
        model: "OY1310"
    };

    node.status({
        fill: "green",
        shape: "dot",
        text: `${volumeLitres} L`
    });

    node.warn(
        `OY1310 VOLUME — ` +
        `device=${devEui}, ` +
        `volume=${volumeLitres} L, ` +
        `fCnt=${payload.fCnt}, ` +
        `rssi=${rssi}`
    );

    return msg;
}

// --------------------------------------------------------------------------
// 0x20 — status report
//
// Typical startup report:
//   01 20 00
// --------------------------------------------------------------------------

if (index === 0x20) {

    const status =
        buf.length >= 3
            ? buf.readUInt8(2)
            : null;

    node.status({
        fill: "blue",
        shape: "ring",
        text:
            status === null
                ? "status"
                : `status 0x${status
                    .toString(16)
                    .padStart(2, "0")}`
    });

    node.warn(
        `OY1310 STATUS — ` +
        `device=${devEui || "unknown"}, ` +
        `status=${status === null
            ? "missing"
            : "0x" +
            status
                .toString(16)
                .padStart(2, "0")
        }, ` +
        `raw=${rawHex}`
    );

    // Status isn't a water-volume measurement.
    return null;
}

// --------------------------------------------------------------------------
// Other Talkpool command/query responses
// --------------------------------------------------------------------------

node.warn(
    `OY1310 unhandled command — ` +
    `device=${devEui || "unknown"}, ` +
    `index=0x${index.toString(16).padStart(2, "0")}, ` +
    `raw=${rawHex}`
);

node.status({
    fill: "yellow",
    shape: "ring",
    text:
        `unhandled 0x${index
            .toString(16)
            .padStart(2, "0")}`
});

return null;

// ── Talkpool OY1310 Configure on Join v1.0 ───────────────────────────────
//
// Configure the OY1310 reporting interval after a successful OTAA join.
//
// FPort 1
// 01 22 00 0F = set measurement interval to 15 minutes
// 0122001E = set to 30 minute interval

const eventType =
    msg.fai?.eventType ||
    String(msg.topic || "")
        .split("/")
        .filter(Boolean)
        .pop();

// Only act on successful join events.
if (eventType !== "join") {
    return null;
}

const deviceInfo =
    msg.payload?.deviceInfo || {};

const applicationId =
    String(deviceInfo.applicationId || "");

const devEui =
    String(deviceInfo.devEui || "").toLowerCase();

if (!applicationId || !devEui) {
    node.warn(
        "OY1310 configuration skipped: missing applicationId or DevEUI"
    );

    return null;
}

const commandHex =
    "0122001E";

const commandBase64 =
    Buffer.from(commandHex, "hex")
        .toString("base64");

msg.topic =
    `application/${applicationId}/device/${devEui}/command/down`;

msg.payload = JSON.stringify({
    devEui: devEui,
    confirmed: false,
    fPort: 1,
    data: commandBase64
});

node.status({
    fill: "blue",
    shape: "dot",
    text: "30 min config queued"
});

node.warn(
    `OY1310 CONFIG QUEUED — ` +
    `device=${devEui}, interval=30min, ` +
    `command=${commandHex}`
);

return msg;

// ── FAI Gateway Parser v10.1 — V2 5 Hz reconstruction + split environment ─
//
// Supports BOTH:
//
//   V2 firmware (current)
//   ---------------------
//   FPort 2 — weight event
//     50 bytes
//     Byte 0:       protocol version = 2
//     Byte 1:       sample count = 23
//     Bytes 2-3:    event number, UInt16 LE
//     Bytes 4-49:   23 × zero-relative weight samples, UInt16 LE
//
//   FPort 3 — environment
//     13 bytes
//     Byte 0:       protocol version = 2
//     Bytes 1-2:    environment packet number, UInt16 LE
//     Bytes 3-4:    temperature × 100, Int16 LE
//     Bytes 5-6:    CO2 ppm, UInt16 LE
//     Bytes 7-8:    light lux, UInt16 LE
//     Bytes 9-10:   humidity × 100, UInt16 LE
//     Bytes 11-12:  pressure × 10, UInt16 LE
//
//   V1 firmware (backward compatibility)
//   ------------------------------------
//   FPort 2 — old combined 50-byte packet
//     Version 1
//     18 weight spot readings + environmental values.
//
// Backend output remains the existing legacy format:
//
//   Type 0x01: environmental packet, 58 bytes, signature 013a.
//   Type 0x02: weight packet,        106 bytes, signature 026a.
//
// V2 weight-window conversion:
//   - One LoRa weight window contains 23 sequential samples at 5 Hz.
//   - One LoRa window becomes up to 23 backend Type 0x02 messages.
//   - Each source sample is repeated across all 50 legacy WeightLoadSample
//     positions, matching the historical backend representation.
//   - Reconstructed backend timestamps are spaced 200 ms apart.
//   - 0xFFFF failed source samples are skipped rather than invented/repaired.
//
// ============================================================================
// Configuration
// ============================================================================

const gatewaySerial =
    env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

const TARGET_CLOUD_SID = 16777216;

const INVALID_WEIGHT = 0xFFFF;

const RECENT_MESSAGE_HISTORY = 64;
const STATE_NAMESPACE = "faiParserV101";

// Current V2 protocol.
const V2_VERSION = 2;

const V2_WEIGHT_PORT = 2;
const V2_WEIGHT_PAYLOAD_LENGTH = 50;
const V2_WEIGHT_SAMPLE_COUNT = 23;
const V2_WEIGHT_INTERVAL_MS = 200;

const V2_ENVIRONMENT_PORT = 3;
const V2_ENVIRONMENT_PAYLOAD_LENGTH = 13;

// Legacy backend weight structure.
const LEGACY_WEIGHT_SAMPLE_COUNT = 50;

// V1 backward compatibility.
// Keep the old parser's 10-second reconstruction behaviour unchanged.
const V1_VERSION = 1;
const V1_PORT = 2;
const V1_PAYLOAD_LENGTH = 50;
const V1_MAX_WEIGHT_SAMPLES = 18;
const V1_WEIGHT_INTERVAL_MS = 10000;

// ============================================================================
// ChirpStack event type
// ============================================================================
//
// This function can safely receive:
//   application/+/device/+/event/+
//
// Join events clear duplicate state for that DevEUI.
// Other non-uplink event types are ignored.

const topicParts =
    String(msg.topic || "")
        .split("/")
        .filter(Boolean);

const eventType =
    topicParts.length > 0
        ? topicParts[topicParts.length - 1]
        : "up";

if (eventType === "join") {
    const joinDevEui =
        msg.payload &&
        msg.payload.deviceInfo &&
        msg.payload.deviceInfo.devEui
            ? String(
                msg.payload.deviceInfo.devEui
            ).toUpperCase()
            : null;

    if (joinDevEui) {
        global.set(
            `${STATE_NAMESPACE}_state_${joinDevEui}`,
            undefined
        );

        node.warn(
            `LoRaWAN session reset after join — device=${joinDevEui}`
        );

        node.status({
            fill: "blue",
            shape: "ring",
            text: `new session ${joinDevEui.slice(-8)}`
        });
    }

    return null;
}

if (eventType !== "up") {
    return null;
}

// ============================================================================
// Validate incoming ChirpStack message
// ============================================================================

if (
    !msg.payload ||
    !msg.payload.deviceInfo ||
    !msg.payload.deviceInfo.devEui ||
    msg.payload.data === undefined ||
    msg.payload.data === null
) {
    node.warn(
        "Invalid ChirpStack message: required payload fields are missing"
    );

    return null;
}

// ============================================================================
// Device identity
// ============================================================================

const devEui =
    String(
        msg.payload.deviceInfo.devEui
    ).toUpperCase();

const uidHex =
    devEui.slice(-8);

if (!/^[0-9A-F]{8}$/.test(uidHex)) {
    node.warn(
        `Invalid DevEUI: ${devEui}`
    );

    return null;
}

const dynamicUid =
    parseInt(uidHex, 16);

if (!Number.isFinite(dynamicUid)) {
    node.warn(
        `Unable to calculate UID from DevEUI: ${devEui}`
    );

    return null;
}

// ============================================================================
// Decode compact LoRaWAN payload
// ============================================================================

let buf;

try {
    if (Buffer.isBuffer(msg.payload.data)) {
        buf = msg.payload.data;
    } else {
        buf = Buffer.from(
            String(msg.payload.data),
            "base64"
        );
    }
} catch (error) {
    node.warn(
        `Unable to decode LoRa payload from ${devEui}: ` +
        error.message
    );

    return null;
}

if (buf.length < 1) {
    node.warn(
        `Empty LoRa payload from ${devEui}`
    );

    return null;
}

const protocolVersion =
    buf.readUInt8(0);

const fPortCandidate =
    msg.payload.fPort !== undefined
        ? msg.payload.fPort
        : (
            msg.payload.fport !== undefined
                ? msg.payload.fport
                : msg.payload.port
        );

const fPort =
    Number(fPortCandidate);

if (
    !Number.isInteger(fPort) ||
    fPort < 1 ||
    fPort > 223
) {
    node.warn(
        `Missing/invalid FPort from ${devEui}: ` +
        `${String(fPortCandidate)}`
    );

    return null;
}

// Ignore unrelated LoRa application traffic.
// This parser handles ShedSensor FPort 2 and FPort 3 only.
if (
    fPort !== V2_WEIGHT_PORT &&
    fPort !== V2_ENVIRONMENT_PORT
) {
    return null;
}

// ============================================================================
// Identify and validate packet format
// ============================================================================

let packetKind = null;
let packetSequence = null;

if (
    protocolVersion === V2_VERSION &&
    fPort === V2_WEIGHT_PORT
) {
    if (
        buf.length !==
        V2_WEIGHT_PAYLOAD_LENGTH
    ) {
        node.warn(
            `Unexpected V2 weight payload length from ${devEui}: ` +
            `${buf.length} bytes; expected ${V2_WEIGHT_PAYLOAD_LENGTH}`
        );

        return null;
    }

    const sampleCount =
        buf.readUInt8(1);

    if (
        sampleCount !==
        V2_WEIGHT_SAMPLE_COUNT
    ) {
        node.warn(
            `Invalid V2 weight sample count from ${devEui}: ` +
            `${sampleCount}; expected ${V2_WEIGHT_SAMPLE_COUNT}`
        );

        return null;
    }

    packetKind = "v2-weight";
    packetSequence =
        buf.readUInt16LE(2);
}
else if (
    protocolVersion === V2_VERSION &&
    fPort === V2_ENVIRONMENT_PORT
) {
    if (
        buf.length !==
        V2_ENVIRONMENT_PAYLOAD_LENGTH
    ) {
        node.warn(
            `Unexpected V2 environment payload length from ${devEui}: ` +
            `${buf.length} bytes; expected ${V2_ENVIRONMENT_PAYLOAD_LENGTH}`
        );

        return null;
    }

    packetKind = "v2-environment";
    packetSequence =
        buf.readUInt16LE(1);
}
else if (
    protocolVersion === V1_VERSION &&
    fPort === V1_PORT
) {
    if (
        buf.length !==
        V1_PAYLOAD_LENGTH
    ) {
        node.warn(
            `Unexpected V1 payload length from ${devEui}: ` +
            `${buf.length} bytes; expected ${V1_PAYLOAD_LENGTH}`
        );

        return null;
    }

    const sampleCount =
        buf.readUInt8(1);

    if (
        sampleCount === 0 ||
        sampleCount >
        V1_MAX_WEIGHT_SAMPLES
    ) {
        node.warn(
            `Invalid V1 weight sample count from ${devEui}: ` +
            sampleCount
        );

        return null;
    }

    packetKind = "v1-combined";
    packetSequence =
        buf.readUInt16LE(2);
}
else {
    node.warn(
        `Unsupported LoRa application packet — ` +
        `device=${devEui}, ` +
        `version=${protocolVersion}, ` +
        `fPort=${fPort}, ` +
        `length=${buf.length}`
    );

    return null;
}

// ============================================================================
// Session-aware duplicate protection
// ============================================================================
//
// The application counters and LoRaWAN frame counter can restart after OTAA.
// Therefore duplicate protection is scoped to the detected LoRaWAN session.

const stateKey =
    `${STATE_NAMESPACE}_state_${devEui}`;

let deviceState =
    global.get(stateKey);

if (
    !deviceState ||
    typeof deviceState !== "object" ||
    Array.isArray(deviceState)
) {
    deviceState = {
        sessionSequence: 0,
        devAddr: null,
        maxFrameCounter: -1,
        recentEventIds: [],
        recentPackets: []
    };
}

if (
    !Array.isArray(
        deviceState.recentEventIds
    )
) {
    deviceState.recentEventIds = [];
}

if (
    !Array.isArray(
        deviceState.recentPackets
    )
) {
    deviceState.recentPackets = [];
}

const normaliseHex = value =>
    String(value || "")
        .replace(/^0x/i, "")
        .replace(/[^0-9a-f]/gi, "")
        .toUpperCase();

const devAddr =
    normaliseHex(
        msg.payload.devAddr
    );

const frameCounter =
    Number(
        msg.payload.fCnt
    );

const hasFrameCounter =
    Number.isInteger(frameCounter) &&
    frameCounter >= 0;

const devAddrChanged =
    devAddr.length > 0 &&
    deviceState.devAddr &&
    devAddr !== deviceState.devAddr;

const frameCounterRestarted =
    hasFrameCounter &&
    frameCounter <= 1 &&
    Number.isInteger(
        deviceState.maxFrameCounter
    ) &&
    deviceState.maxFrameCounter > 1;

if (
    devAddrChanged ||
    frameCounterRestarted
) {
    deviceState.sessionSequence =
        Number(
            deviceState.sessionSequence || 0
        ) + 1;

    deviceState.recentEventIds = [];
    deviceState.recentPackets = [];
    deviceState.maxFrameCounter = -1;

    node.warn(
        `New LoRaWAN session detected — ` +
        `device=${devEui}, ` +
        `devAddr=${devAddr || "unknown"}, ` +
        `fCnt=${hasFrameCounter ? frameCounter : "unknown"}`
    );
}

if (devAddr.length > 0) {
    deviceState.devAddr =
        devAddr;
}

const payloadHex =
    buf.toString("hex");

const deduplicationId =
    String(
        msg.payload.deduplicationId || ""
    ).trim();

const exactEventSignature =
    deduplicationId
        ? `dedup:${deduplicationId}`
        : (
            devAddr.length > 0 &&
            hasFrameCounter
                ? (
                    `frame:${devAddr}:` +
                    `${frameCounter}:` +
                    `${fPort}:` +
                    `${payloadHex}`
                )
                : (
                    `payload:${fPort}:` +
                    `${packetSequence}:` +
                    `${payloadHex}`
                )
        );

if (
    deviceState.recentEventIds.includes(
        exactEventSignature
    )
) {
    node.warn(
        `Ignoring duplicate ChirpStack event — ` +
        `device=${devEui}, ` +
        `kind=${packetKind}, ` +
        `sequence=${packetSequence}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `duplicate ${packetKind} ${packetSequence}`
    });

    return null;
}

const sessionIdentity =
    `session:${Number(deviceState.sessionSequence || 0)}:` +
    `${deviceState.devAddr || "unknown"}`;

const applicationPacketSignature =
    `${sessionIdentity}:` +
    `${packetKind}:` +
    `${packetSequence}:` +
    `${payloadHex}`;

if (
    deviceState.recentPackets.includes(
        applicationPacketSignature
    )
) {
    node.warn(
        `Ignoring retransmitted application packet — ` +
        `device=${devEui}, ` +
        `kind=${packetKind}, ` +
        `sequence=${packetSequence}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `retransmitted ${packetKind} ${packetSequence}`
    });

    return null;
}

deviceState.recentEventIds.push(
    exactEventSignature
);

deviceState.recentPackets.push(
    applicationPacketSignature
);

if (
    deviceState.recentEventIds.length >
    RECENT_MESSAGE_HISTORY
) {
    deviceState.recentEventIds =
        deviceState.recentEventIds.slice(
            -RECENT_MESSAGE_HISTORY
        );
}

if (
    deviceState.recentPackets.length >
    RECENT_MESSAGE_HISTORY
) {
    deviceState.recentPackets =
        deviceState.recentPackets.slice(
            -RECENT_MESSAGE_HISTORY
        );
}

if (hasFrameCounter) {
    deviceState.maxFrameCounter =
        Math.max(
            Number(
                deviceState.maxFrameCounter || -1
            ),
            frameCounter
        );
}

global.set(
    stateKey,
    deviceState
);

// ============================================================================
// RSSI
// ============================================================================

let bestRssi = -120;

if (
    Array.isArray(
        msg.payload.rxInfo
    ) &&
    msg.payload.rxInfo.length > 0
) {
    const validRssiValues =
        msg.payload.rxInfo
            .map(
                rx => Number(rx.rssi)
            )
            .filter(
                value => Number.isFinite(value)
            );

    if (
        validRssiValues.length > 0
    ) {
        bestRssi =
            Math.max(
                ...validRssiValues
            );
    }
}

const rawRssi =
    Math.abs(bestRssi);

// ============================================================================
// Timestamp helpers
// ============================================================================
//
// Node-RED processing time anchors each received packet because the V2
// firmware does not currently transmit an RTC timestamp. For V2 weight data,
// the preceding 22 samples are reconstructed backwards at 200 ms intervals.

function formatBackendTimestamp(date) {
    // Preserve milliseconds because V2 weight samples are 200 ms apart.
    return date
        .toISOString()
        .replace("Z", "+00:00");
}

const receivedTime =
    new Date();

const receivedTimestamp =
    formatBackendTimestamp(
        receivedTime
    );

// ============================================================================
// Backend message helpers
// ============================================================================

const outMessages = [];

const usedPacketNumbers =
    new Set();

function nextPacketNumber() {
    let packetNumber;

    do {
        packetNumber =
            Math.floor(
                Math.random() * 65536
            );
    } while (
        usedPacketNumbers.has(
            packetNumber
        )
    );

    usedPacketNumbers.add(
        packetNumber
    );

    return packetNumber;
}

function makeBackendMessage(
    hexData,
    timestamp
) {
    return {
        topic:
            `gateway/${gatewaySerial}/tinymesh/out`,

        payload: {
            "_meta": {
                "received": timestamp
            },

            "block": 0,
            "data": hexData,
            "detail": "serial",
            "hops": 1,
            "latency": 2,
            "network_lvl": 1,
            "packet_num": nextPacketNumber(),
            "rssi": rawRssi,
            "sid": TARGET_CLOUD_SID,
            "type": "event",
            "uid": dynamicUid
        }
    };
}

// ============================================================================
// Legacy Type 0x01 environmental packet
// ============================================================================
//
// Type:      0x01
// Length:    58 bytes
// Signature: 013a

function makeEnvironmentMessage(
    temperature,
    pressure,
    humidity,
    lux,
    co2,
    timestamp
) {
    const envBuf =
        Buffer.alloc(58, 0);

    envBuf.writeUInt8(
        0x01,
        0
    );

    envBuf.writeUInt8(
        0x3A,
        1
    );

    // Bytes 2-5 remain reserved and zero-filled.

    envBuf.writeFloatLE(
        temperature,
        6
    );

    envBuf.writeFloatLE(
        pressure,
        10
    );

    envBuf.writeFloatLE(
        temperature,
        14
    );

    envBuf.writeFloatLE(
        humidity,
        18
    );

    envBuf.writeUInt32LE(
        Math.min(
            0xFFFFFFFF,
            Math.max(
                0,
                Math.round(lux)
            )
        ),
        22
    );

    // Confirmed backend workaround retained from v9.1:
    // GASCO2 must be UInt32, not Float32.
    envBuf.writeUInt32LE(
        Math.min(
            0xFFFFFFFF,
            Math.max(
                0,
                Math.round(co2)
            )
        ),
        26
    );

    envBuf.writeFloatLE(
        0.0,
        30
    );

    envBuf.writeFloatLE(
        0.0,
        34
    );

    envBuf.writeFloatLE(
        0.0,
        38
    );

    envBuf.writeFloatLE(
        0.0,
        42
    );

    envBuf.writeFloatLE(
        0.0,
        46
    );

    envBuf.writeFloatLE(
        temperature,
        50
    );

    envBuf.writeFloatLE(
        temperature,
        54
    );

    return makeBackendMessage(
        envBuf.toString("hex"),
        timestamp
    );
}

// ============================================================================
// Legacy Type 0x02 weight packet
// ============================================================================
//
// Type:      0x02
// Length:    106 bytes
// Signature: 026a

function makeWeightMessage(
    legacySamples,
    timestamp
) {
    const wBuf =
        Buffer.alloc(106, 0);

    wBuf.writeUInt8(
        0x02,
        0
    );

    wBuf.writeUInt8(
        0x6A,
        1
    );

    // Bytes 2-5 remain reserved and zero-filled.

    for (
        let i = 0;
        i < LEGACY_WEIGHT_SAMPLE_COUNT;
        i++
    ) {
        const value =
            Math.min(
                65534,
                Math.max(
                    0,
                    Math.round(
                        legacySamples[i] || 0
                    )
                )
            );

        wBuf.writeUInt16LE(
            value,
            6 + (i * 2)
        );
    }

    return makeBackendMessage(
        wBuf.toString("hex"),
        timestamp
    );
}

// ============================================================================
// Decode packet
// ============================================================================

if (packetKind === "v2-weight") {
    const sampleCount =
        buf.readUInt8(1);

    const eventNumber =
        buf.readUInt16LE(2);

    const sourceSamples = [];

    for (
        let i = 0;
        i < sampleCount;
        i++
    ) {
        sourceSamples.push(
            buf.readUInt16LE(
                4 + (i * 2)
            )
        );
    }

    // ------------------------------------------------------------------------
    // V2 weight reconstruction
    // ------------------------------------------------------------------------
    //
    // Firmware supplies 23 sequential weight measurements at 5 Hz.
    //
    // Do NOT spread those 23 measurements across WeightLoadSample1..50.
    //
    // Instead, generate one legacy Type 0x02 backend message per valid source
    // sample. Within each backend message, repeat that single measured value
    // across all 50 legacy WeightLoadSample positions. This mirrors the old
    // parser/backend representation while preserving the new 200 ms sequence.
    // ------------------------------------------------------------------------

    const newestSampleTime =
        receivedTime;

    let validWeightSamples = 0;
    let invalidWeightSamples = 0;
    let genuineZeroSamples = 0;

    let sourceMinimum = null;
    let sourceMaximum = null;

    for (
        let i = 0;
        i < sampleCount;
        i++
    ) {
        const weight =
            sourceSamples[i];

        // 0xFFFF means this scale point failed. Do not fabricate a replacement.
        if (
            weight === INVALID_WEIGHT
        ) {
            invalidWeightSamples++;
            continue;
        }

        const outputWeight =
            Math.min(
                65534,
                Math.max(
                    0,
                    Math.round(weight)
                )
            );

        if (
            outputWeight === 0
        ) {
            genuineZeroSamples++;
        }

        if (
            sourceMinimum === null ||
            outputWeight < sourceMinimum
        ) {
            sourceMinimum =
                outputWeight;
        }

        if (
            sourceMaximum === null ||
            outputWeight > sourceMaximum
        ) {
            sourceMaximum =
                outputWeight;
        }

        // Treat the last source point as the newest point and reconstruct the
        // preceding samples backwards using the actual firmware interval.
        const ageFromNewestMs =
            (
                sampleCount -
                1 -
                i
            ) *
            V2_WEIGHT_INTERVAL_MS;

        const sampleTime =
            new Date(
                newestSampleTime.getTime() -
                ageFromNewestMs
            );

        const sampleTimestamp =
            formatBackendTimestamp(
                sampleTime
            );

        // Historical backend representation:
        // one measured weight repeated through all 50 WeightLoadSample fields.
        const legacySamples =
            new Array(
                LEGACY_WEIGHT_SAMPLE_COUNT
            ).fill(
                outputWeight
            );

        outMessages.push(
            makeWeightMessage(
                legacySamples,
                sampleTimestamp
            )
        );

        validWeightSamples++;
    }

    node.warn(
        `V2 WEIGHT WINDOW DECODED — ` +
        `device=${devEui}, ` +
        `window=${eventNumber}, ` +
        `sourceSamples=${sampleCount}, ` +
        `valid=${validWeightSamples}, ` +
        `invalid=${invalidWeightSamples}, ` +
        `zeros=${genuineZeroSamples}, ` +
        `min=${sourceMinimum === null ? "none" : sourceMinimum}, ` +
        `max=${sourceMaximum === null ? "none" : sourceMaximum}, ` +
        `backendMessages=${validWeightSamples}`
    );

    node.status({
        fill:
            invalidWeightSamples > 0
                ? "yellow"
                : "green",

        shape: "dot",

        text:
            `weight window ${eventNumber} -> ${validWeightSamples} samples`
    });
}
else if (
    packetKind === "v2-environment"
) {
    const environmentPacketNumber =
        buf.readUInt16LE(1);

    const temperature =
        buf.readInt16LE(3) /
        100.0;

    const co2 =
        buf.readUInt16LE(5);

    const lux =
        buf.readUInt16LE(7);

    const humidity =
        buf.readUInt16LE(9) /
        100.0;

    const pressure =
        buf.readUInt16LE(11) /
        10.0;

    outMessages.push(
        makeEnvironmentMessage(
            temperature,
            pressure,
            humidity,
            lux,
            co2,
            receivedTimestamp
        )
    );

    node.warn(
        `V2 ENVIRONMENT DECODED — ` +
        `device=${devEui}, ` +
        `packet=${environmentPacketNumber}, ` +
        `temperature=${temperature}, ` +
        `pressure=${pressure}, ` +
        `humidity=${humidity}, ` +
        `lux=${lux}, ` +
        `co2=${co2}, ` +
        `backendMessages=1`
    );

    node.status({
        fill: "green",
        shape: "dot",
        text:
            `environment ${environmentPacketNumber} -> 1 backend packet`
    });
}
else if (
    packetKind === "v1-combined"
) {
    // ------------------------------------------------------------------------
    // Backward-compatible path for the old combined V1 packet.
    // This deliberately preserves the v9.1 behaviour.
    // ------------------------------------------------------------------------

    const sampleCount =
        buf.readUInt8(1);

    const batchNumber =
        buf.readUInt16LE(2);

    const temperature =
        buf.readInt16LE(40) /
        100.0;

    const co2 =
        buf.readUInt16LE(42);

    const lux =
        buf.readUInt16LE(44);

    const humidity =
        buf.readUInt16LE(46) /
        100.0;

    const pressure =
        buf.readUInt16LE(48) /
        10.0;

    let validWeightEvents = 0;
    let invalidWeightEvents = 0;
    let genuineZeroEvents = 0;

    const newestSampleTime =
        receivedTime;

    for (
        let i = 0;
        i < sampleCount;
        i++
    ) {
        const weight =
            buf.readUInt16LE(
                4 + (i * 2)
            );

        const ageFromNewestMs =
            (
                sampleCount -
                1 -
                i
            ) *
            V1_WEIGHT_INTERVAL_MS;

        const sampleTime =
            new Date(
                newestSampleTime.getTime() -
                ageFromNewestMs
            );

        const sampleTimestamp =
            formatBackendTimestamp(
                sampleTime
            );

        if (
            weight ===
            INVALID_WEIGHT
        ) {
            invalidWeightEvents++;

            continue;
        }

        const outputWeight =
            Math.min(
                65534,
                Math.max(
                    0,
                    Math.round(weight)
                )
            );

        if (
            outputWeight === 0
        ) {
            genuineZeroEvents++;
        }

        const legacySamples =
            new Array(
                LEGACY_WEIGHT_SAMPLE_COUNT
            ).fill(
                outputWeight
            );

        outMessages.push(
            makeWeightMessage(
                legacySamples,
                sampleTimestamp
            )
        );

        validWeightEvents++;
    }

    outMessages.push(
        makeEnvironmentMessage(
            temperature,
            pressure,
            humidity,
            lux,
            co2,
            receivedTimestamp
        )
    );

    node.warn(
        `V1 COMBINED BATCH DECODED — ` +
        `device=${devEui}, ` +
        `batch=${batchNumber}, ` +
        `samples=${sampleCount}, ` +
        `validWeights=${validWeightEvents}, ` +
        `invalidWeights=${invalidWeightEvents}, ` +
        `genuineZeros=${genuineZeroEvents}, ` +
        `backendMessages=${outMessages.length}`
    );

    node.status({
        fill:
            invalidWeightEvents > 0
                ? "yellow"
                : "green",

        shape: "dot",

        text:
            `${validWeightEvents} V1 weights + 1 env`
    });
}

// ============================================================================
// Send all generated backend messages through output 1
// ============================================================================

if (outMessages.length === 0) {
    return null;
}

node.send(
    [outMessages]
);

return null;

// ── FAI Talkpool OY1310 → wM-Bus Backend Formatter ───────────────────────
//
// Purpose:
//   Make a decoded Talkpool OY1310 LoRaWAN measurement look like the
//   existing MC100 / wM-Bus message contract.
//
// SerialNumber:
//   Equivalent to Excel:
//   =HEX2DEC(RIGHT(DevEUI, 8))
//
// Example:
//   DevEUI:       70B3D5D72004216A
//   Last 8 hex:   2004216A
//   SerialNumber: 537141610
//
// Output:
//   Same topic, outer JSON structure and field names as existing wM-Bus.
//
// --------------------------------------------------------------------------

const gatewaySerial =
    env.get("GATEWAY_SERIAL") || "UNKNOWN_GW";

const p =
    msg.payload || {};


// ==========================================================================
// 1. GET AND VALIDATE DEVEUI
// ==========================================================================

const devEui =
    String(
        p.dev_eui ||
        msg.fai?.devEui ||
        ""
    )
    .replace(/^0x/i, "")
    .replace(/[^0-9a-f]/gi, "")
    .toUpperCase();


if (devEui.length !== 16) {

    node.warn(
        `Talkpool formatter: invalid DevEUI "${devEui}"`
    );

    node.status({
        fill: "red",
        shape: "ring",
        text: "invalid DevEUI"
    });

    return null;
}


// ==========================================================================
// 2. DERIVE BACKEND SERIAL NUMBER
//
// Equivalent to:
// =HEX2DEC(RIGHT(DevEUI, 8))
// ==========================================================================

const serialHex =
    devEui.slice(-8);

const serialDecimal =
    parseInt(serialHex, 16);

if (!Number.isFinite(serialDecimal)) {

    node.warn(
        `Talkpool formatter: unable to derive serial from ${devEui}`
    );

    return null;
}

const serialNumber =
    String(serialDecimal);


// ==========================================================================
// 3. VALIDATE TALKPOOL WATER READING
//
// Parser should already have decoded:
// 01 21 XX XX XX XX
//
// into volume_litres.
// ==========================================================================

const volumeLitres =
    Number(p.volume_litres);

if (!Number.isFinite(volumeLitres)) {

    node.warn(
        `Talkpool formatter: missing/invalid water volume ` +
        `for serial ${serialNumber}`
    );

    return null;
}


// ==========================================================================
// 4. MANUFACTURER
//
// Use TPL as the 3-character compatibility manufacturer identifier.
// Encode it using the normal M-Bus 3-letter manufacturer calculation.
// ==========================================================================

const manufacturer =
    "TPL";

const manInt =
    ((manufacturer.charCodeAt(0) - 64) << 10) |
    ((manufacturer.charCodeAt(1) - 64) << 5) |
    (manufacturer.charCodeAt(2) - 64);


// ==========================================================================
// 5. RAW TALKPOOL APPLICATION PAYLOAD
//
// Talkpool parser supplies p.raw as HEX.
//
// Existing wM-Bus packet sends "raw" as Base64, so convert it to Base64.
// ==========================================================================

const rawHex =
    String(p.raw || "")
        .replace(/[^0-9a-f]/gi, "");

if (
    !rawHex ||
    rawHex.length % 2 !== 0
) {

    node.warn(
        `Talkpool formatter: invalid raw payload ` +
        `for serial ${serialNumber}`
    );

    return null;
}

const base64Raw =
    Buffer
        .from(rawHex, "hex")
        .toString("base64");


// ==========================================================================
// 6. BUILD wM-Bus-COMPATIBLE IDENTIFICATION FIELDS
// ==========================================================================

// Existing wM-Bus parser sends a 20-character AField.
//
// Here we preserve the final 32-bit DevEUI portion as the identifier
// component and pad the remaining compatibility bytes.
//
// Example:
// 2004216A + 000000000000
const aField =
    serialHex +
    "000000000000";


// Existing MC100 parser convention:
// ID = "18" + SerialNumber
const id =
    "18" + serialNumber;


// ==========================================================================
// 7. SAME MQTT TOPIC AS EXISTING wM-Bus
// ==========================================================================

msg.topic =
    `gateway/${gatewaySerial}/wmbus/out`;


// ==========================================================================
// 8. EXACT SAME OUTER CONTRACT AS EXISTING wM-Bus EXTRACTOR
// ==========================================================================

msg.payload = {

    "_meta": {

        "received":
            p.timestamp ||
            new Date()
                .toISOString()
                .split(".")[0] + "+00:00",

        "receiver_id":
            "0000000000000000",

        "rssi":
            Number.isFinite(Number(p.rssi))
                ? Number(p.rssi)
                : -52
    },


    "data": {

        "AField":
            aField.toUpperCase(),

        "CField":
            68,

        "CIField":
            114,

        "ID":
            id,

        "LField":
            Buffer.from(rawHex, "hex").length,

        "MField":
            manInt,

        "Manufacturer":
            manufacturer,

        "SerialNumber":
            serialNumber
    },


    "raw":
        base64Raw,


    "type":
        "wmbus"
};


// ==========================================================================
// 9. NODE-RED STATUS
// ==========================================================================

node.status({

    fill: "green",
    shape: "dot",

    text:
        `${serialNumber}: ${volumeLitres} L`
});

node.warn(

    `OY1310 → wM-Bus — ` +
    `DevEUI=${devEui}, ` +
    `Serial=${serialNumber}, ` +
    `Volume=${volumeLitres} L`
);


return msg;

// ── FAI Talkpool → wM-Bus AES Encrypter ──────────────────────────────────
//
// Input:
//   msg.payload already formatted to the existing wM-Bus backend contract.
//
// Key lookup:
//   SerialNumber -> AES-128 key
//
// Environment variable:
//   TALKPOOL_WMBUS_KEYS_JSON
//
// Example:
// {
//   "537141610": "00112233445566778899AABBCCDDEEFF",
//   "123456789": "FFEEDDCCBBAA99887766554433221100"
// }
//
// IMPORTANT:
//   The AES key is NEVER added to msg.payload or MQTT.
// --------------------------------------------------------------------------

const packet = msg.payload || {};
const data = packet.data || {};

const serialNumber =
    String(data.SerialNumber || "").trim();

if (!serialNumber) {
    node.warn("wM-Bus encrypter: SerialNumber missing");
    return null;
}


// ==========================================================================
// 1. LOAD KEY LIST
// ==========================================================================

let keys;

try {

    const rawKeyList =
        env.get("TALKPOOL_WMBUS_KEYS_JSON") || '{"537141610": "e17cc072e4d86e4d13a0ae4f70e2e51a"}';

    keys =
        JSON.parse(rawKeyList);

} catch (err) {

    node.warn(
        `wM-Bus encrypter: invalid TALKPOOL_WMBUS_KEYS_JSON — ${err.message}`
    );

    node.status({
        fill: "red",
        shape: "ring",
        text: "invalid key configuration"
    });

    return null;
}


// ==========================================================================
// 2. FIND KEY FOR THIS SERIAL
// ==========================================================================

const keyHex =
    String(keys[serialNumber] || "")
        .replace(/\s+/g, "")
        .toUpperCase();

if (!keyHex) {

    node.warn(
        `wM-Bus encrypter: no AES key configured for ${serialNumber}`
    );

    node.status({
        fill: "yellow",
        shape: "ring",
        text: `no key ${serialNumber}`
    });

    return null;
}


// ==========================================================================
// 3. VALIDATE AES-128 KEY
// ==========================================================================

if (!/^[0-9A-F]{32}$/.test(keyHex)) {

    node.warn(
        `wM-Bus encrypter: invalid AES-128 key format for ${serialNumber}`
    );

    node.status({
        fill: "red",
        shape: "ring",
        text: `bad key ${serialNumber}`
    });

    return null;
}

const aesKey =
    Buffer.from(keyHex, "hex");


// ==========================================================================
// 4. GET TALKPOOL WATER READING
//
// At this point the formatter needs to preserve the decoded volume for this
// internal encryption step. It must NOT be added to the final MQTT payload.
// ==========================================================================

const volumeLitres =
    Number(msg._talkpoolVolumeLitres);

if (!Number.isFinite(volumeLitres)) {

    node.warn(
        `wM-Bus encrypter: volume missing for ${serialNumber}`
    );

    return null;
}


// ==========================================================================
// 5. BUILD THE PLAINTEXT wM-Bus APPLICATION DATA
//
// DO NOT GUESS THIS PART.
//
// We need to reproduce the exact DIF/VIF / security structure that the
// existing mbusconsumer expects.
//
// Example conceptual result:
//
//   accumulated volume = volumeLitres
//
// const plainFrame = buildWmbusPayload(
//     serialNumber,
//     volumeLitres
// );
//
// ==========================================================================


// ==========================================================================
// 6. ENCRYPT USING THE SAME wM-Bus SECURITY MODE AS THE BACKEND
//
// Again, this must match the existing mbusconsumer exactly.
//
// const encryptedFrame = encryptWmbus(
//     plainFrame,
//     aesKey,
//     ...
// );
//
// packet.raw = encryptedFrame.toString("base64");
//
// ==========================================================================


// TEMPORARY: stop here until the actual backend wM-Bus crypto format
// is confirmed.

node.status({
    fill: "blue",
    shape: "ring",
    text: `key found ${serialNumber}`
});

node.warn(
    `wM-Bus key resolved — serial=${serialNumber}, ` +
    `volume=${volumeLitres}L`
);

return null;

const now = Date.now();
const startedAt = global.get("health_started_at") || now;
if (!global.get("health_started_at")) global.set("health_started_at", startedAt);

const emcMode = String(env.get("EMC_TEST_MODE") || "false").toLowerCase() === "true";
const staleSeconds = Number(env.get("NODE_RED_HEALTH_STALE_SECONDS") || 25);
const startupGraceSeconds = Number(env.get("NODE_RED_HEALTH_STARTUP_GRACE_SECONDS") || 30);
const inStartupGrace = now - startedAt < startupGraceSeconds * 1000;

const tinyLast = Number(global.get("health_tinymesh_last_seen") || 0);
const wmbusLast = Number(global.get("health_wmbus_last_seen") || 0);
const tinyAge = tinyLast ? (now - tinyLast) / 1000 : null;
const wmbusAge = wmbusLast ? (now - wmbusLast) / 1000 : null;
const tinySerialBad = global.get("health_tinymesh_serial_bad") === true;
const wmbusSerialBad = global.get("health_wmbus_serial_bad") === true;

const failures = [];
if (!inStartupGrace && tinySerialBad) failures.push("tinymesh_serial");
if (!inStartupGrace && wmbusSerialBad) failures.push("wmbus_serial");

// Radio data freshness is monitored separately by the EMC monitor and
// targeted radio recovery logic. It must not make the whole Node-RED
// container unhealthy and trigger Docker autoheal.

const healthy = failures.length === 0;
msg.statusCode = healthy ? 200 : 503;
msg.headers = { "content-type": "application/json", "cache-control": "no-store" };
msg.payload = {
    status: healthy ? "ok" : "fail",
    timestamp: new Date(now).toISOString(),
    emc_test_mode: emcMode,
    startup_grace: inStartupGrace,
    failures,
    tinymesh: { age_seconds: tinyAge, serial_bad: tinySerialBad },
    wmbus: { age_seconds: wmbusAge, serial_bad: wmbusSerialBad }
};
return msg;
